-- 简体化清理：台湾用词与繁体字
--
-- 两类问题：
--   A. 台湾用词——字是简体字，词是台湾译法（食人妖/不死族/哥布林/夜精灵）。
--      规范写法取自 wowhead zhCN（巨魔/亡灵/地精/暗夜精灵），也说通了库内既有名称。
--   B. 繁体字残留——如 麽/後/於/紮/夥/勳/蠍/蹟，来自繁体文本直接转码。
--      用 OpenCC t2s（词组级）转换：乾坤/瞭望/哪吒 等会正确保留。
--
-- 例外（有意保留）：吒（人名用字，OpenCC 会误转成咤）、覆上土（覆→复 只适用于「回覆/反覆」）。
--
-- 生效：`.reload locales_quest` / `locales_page_text` / `locales_broadcast_text` /
--       `locales_creature` / `locales_item` / `locales_gameobject` / `locales_spell` /
--       `mangos_string` / `script_texts`




-- ---- 副名（职业名，wowhead 已确认）----
UPDATE `locales_creature` SET `subname_loc4` = '潜行者训练师' WHERE `subname_loc4` = '盗贼训练师';
UPDATE `locales_creature` SET `subname_loc4` = '祖师级潜行者' WHERE `subname_loc4` = '宗师级盗贼';
UPDATE `locales_creature` SET `subname_loc4` = '地精卫兵' WHERE `subname_loc4` = '哥布林卫兵';

-- ---- Rogue/Thief 系物品（wowhead 已确认用「潜行者」）----
