UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这个报告……我们夜精灵已经知道里面提到的威胁了。菲兹杜瑟让你把这份报告送到我这里来是很明智的。$B$B这些生物会迅速吞噬塔纳利斯的沙漠，它们将是我们所要面对的有史以来最大的威胁。$N，请记住它们的名字:异种蝎。报告里提到的这些昆虫就是异种蝎，它们对于部落和联盟来说都是一个威胁。$B$B除非我们能够早点意识到它的危害程度，否则后果不堪设想。$B$B' WHERE `entry` = 162 AND `OfferRewardText_loc4` = '这个报告……我们夜精灵已经知道里面提到的威胁了。菲兹杜瑟让你把这份报告送到我这里来是很明智的。$B$B这些生物会迅速吞噬塔纳利斯的沙漠，它们将是我们所要面对的有史以来最大的威胁。$N，请记住它们的名字:异种蠍。报告里提到的这些昆虫就是异种蠍，它们对於部落和联盟来说都是一个威胁。$B$B除非我们能够早点意识到它的危害程度，否则後果不堪设想。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '伊莲·克尔文?呵呵，是的……当然，克尔文家的。不不不，我没什么事，只是现在要去镇上很困难。路上太危险了，而我已经不再年轻。你能帮帮我这个老头子吗?$B$B' WHERE `entry` = 165 AND `OfferRewardText_loc4` = '伊莲·克尔文?呵呵，是的……当然，克尔文家的。不不不，我没什麽事，只是现在要去镇上很困难。路上太危险了，而我已经不再年轻。你能帮帮我这个老头子吗?$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '$N，你的英雄壮举将长存于我们的心中。人民军将会对你为西部荒野人民所做的一切感激不尽。范克里夫一死，迪菲亚兄弟会的命运也开始走向灭亡。希望在不久之后的某一天，和平会重新降临到这片美丽的土地上。$B$B我向你致敬，$G先生:女士;!$B$B' WHERE `entry` = 166 AND `OfferRewardText_loc4` = '$N，你的英雄壮举将长存於我们的心中。人民军将会对你为西部荒野人民所做的一切感激不尽。范克里夫一死，迪菲亚兄弟会的命运也开始走向灭亡。希望在不久之後的某一天，和平会重新降临到这片美丽的土地上。$B$B我向你致敬，$G先生:女士;!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '感谢你找回这些东西，$N。你的努力一定能使这些不幸死于事故的矿工们得到安息。我会马上通知他们的家人。$B$B' WHERE `entry` = 168 AND `OfferRewardText_loc4` = '感谢你找回这些东西，$N。你的努力一定能使这些不幸死於事故的矿工们得到安息。我会马上通知他们的家人。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '如果我们的土地上到处都是我们遇到的这些讨厌的家伙，以麦格尼胡须的名义，那我们就有大麻烦了!我只能盼望国王和参议院能尽快着手解决石腭怪带来的问题。$B$B' WHERE `entry` = 170 AND `OfferRewardText_loc4` = '如果我们的土地上到处都是我们遇到的这些讨厌的家伙，以麦格尼胡须的名义，那我们就有大麻烦了!我只能盼望国王和参议院能尽快着手解决石齶怪带来的问题。$B$B';
