UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊!那些天杀的食人妖!$B$B<他深吸了几口气，似乎想平静下来……>$B$B一伙食人妖趁着夜色溜了进来，把我的日记给偷走了!我就知道我那没用的学……$B$B' WHERE `entry` = 182 AND `OfferRewardText_loc4` = '啊!那些天杀的食人妖!$B$B<他深吸了几口气，似乎想平静下来……>$B$B一夥食人妖趁着夜色溜了进来，把我的日记给偷走了!我就知道我那没用的学……$B$B';
