UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我几乎有点不敢相信了，但你给我们带回了确实的证据……库尔森和他的副手们都已经被消灭了!你拯救了我们!$B$B这片丛林中有着无数隐藏着的威胁，但只有库尔森才是真正集残酷、邪恶和智慧于一身的敌人。现在他死了，我们都可以松一口气了。$B$B' WHERE `entry` = 202 AND `OfferRewardText_loc4` = '我几乎有点不敢相信了，但你给我们带回了确实的证据……库尔森和他的副手们都已经被消灭了!你拯救了我们!$B$B这片丛林中有着无数隐藏着的威胁，但只有库尔森才是真正集残酷、邪恶和智慧於一身的敌人。现在他死了，我们都可以松一口气了。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '谢谢你，$N。我会仔细研究这些食人妖传说，找出食人妖到底是用什么样的邪恶魔法控制了库尔森上校!$B$B' WHERE `entry` = 207 AND `OfferRewardText_loc4` = '谢谢你，$N。我会仔细研究这些食人妖传说，找出食人妖到底是用什麽样的邪恶魔法控制了库尔森上校!$B$B';
