UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<一个虚无缥缈的声音在风中响起……>$B$B这是……萨拉?她还活着吗?现在我肩上的重担终于可以卸下了……$B$B$N。拿走我的剑…拿走阿契厄斯吧……我再也不需要它了，因为我的灵魂终于可以安息了。我努力想要做一个好人，可是我不配再拿着这把剑，你可以继续带着这把光明的圣剑。$B$B莉丝，我的挚爱……$B$B' WHERE `entry` = 231 AND `OfferRewardText_loc4` = '<一个虚无缥缈的声音在风中响起……>$B$B这是……萨拉?她还活着吗?现在我肩上的重担终於可以卸下了……$B$B$N。拿走我的剑…拿走阿契厄斯吧……我再也不需要它了，因为我的灵魂终於可以安息了。我努力想要做一个好人，可是我不配再拿着这把剑，你可以继续带着这把光明的圣剑。$B$B莉丝，我的挚爱……$B$B';
