UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<他很快地看了一下这份报告。>$B$B国王授权的?!麦格尼已经完全丧失判断力了!那个该死的白须……他控制了整个事态，难道不是吗?参议院一定会对此很恼怒的，而且不是一点点!$B$B怎么，你还在这里?快滚，不然我要喊卫兵了!$B$B' WHERE `entry` = 291 AND `OfferRewardText_loc4` = '<他很快地看了一下这份报告。>$B$B国王授权的?!麦格尼已经完全丧失判断力了!那个该死的白须……他控制了整个事态，难道不是吗?参议院一定会对此很恼怒的，而且不是一点点!$B$B怎麽，你还在这里?快滚，不然我要喊卫兵了!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '帕雷斯之眼。不过这一只眼睛看见过太多的哀伤……它一定目睹过一场极其可怕的悲剧。$B$B让我来净化它，制造帕雷斯之眼是为了圣光服务的，如果它受污染成这个样子，那么它的魔力就会变得非常危险。$B$B' WHERE `entry` = 293 AND `OfferRewardText_loc4` = '帕雷斯之眼。不过这一只眼睛看见过太多的哀伤……它一定目睹过一场极其可怕的悲剧。$B$B让我来净化它，制造帕雷斯之眼是为了圣光服务的，如果它受污染成这个样子，那麽它的魔力就会变得非常危险。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你拿到了!干得好，$N!$B$B这个任务对你来说似乎并不困难，周围这么多疯狂的穴居人都没能把你怎么样。我会关注你的……你看起来挺有前途的。$B$B' WHERE `entry` = 297 AND `OfferRewardText_loc4` = '你拿到了!干得好，$N!$B$B这个任务对你来说似乎并不困难，周围这麽多疯狂的穴居人都没能把你怎麽样。我会关注你的……你看起来挺有前途的。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，戈奥兹之石终于完成了!干得太好啦，$N。现在我终于可以继续翻译这份泰坦留下的手稿了。我可以从里面解读出许多新的内容!嗯......这里写着，「上古诸神...被禁锢于大地下的深渊中。」这一定是某段史诗的开头部分。$B$B' WHERE `entry` = 299 AND `OfferRewardText_loc4` = '啊，戈奥兹之石终於完成了!干得太好啦，$N。现在我终於可以继续翻译这份泰坦留下的手稿了。我可以从里面解读出许多新的内容!嗯......这里写着，「上古诸神...被禁锢於大地下的深渊中。」这一定是某段史诗的开头部分。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '该死的家伙!几个星期前我给他送去了足够把塞尔萨玛炸上天的火药粉，这个报告里却连一个字都没提!$B$B那么……火药粉都上哪儿去了?!$B$B' WHERE `entry` = 301 AND `OfferRewardText_loc4` = '该死的家伙!几个星期前我给他送去了足够把塞尔萨玛炸上天的火药粉，这个报告里却连一个字都没提!$B$B那麽……火药粉都上哪儿去了?!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '什么?勘察员塔伯斯·雷矛叫你亲自护送这批货到铁环挖掘场去?$B$B我……我看这样挺好。唯一的问题是，我已经让胡达尔跟着搬运工米兰和赛恩一起去了。他们刚刚才出发，你正好错过了。$B$B' WHERE `entry` = 302 AND `OfferRewardText_loc4` = '什麽?勘察员塔伯斯·雷矛叫你亲自护送这批货到铁环挖掘场去?$B$B我……我看这样挺好。唯一的问题是，我已经让胡达尔跟着搬运工米兰和赛恩一起去了。他们刚刚才出发，你正好错过了。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你出色地完成了任务，$C。你已经向麦格尼陛下证明了你的忠诚与勇敢，为此，我向你致敬!你对黑铁矮人进行了沉重的打击，如今我们终于有机会将他们彻底赶出我们的国土了……希望这群家伙不再耍什么花样……$B$B' WHERE `entry` = 303 AND `OfferRewardText_loc4` = '你出色地完成了任务，$C。你已经向麦格尼陛下证明了你的忠诚与勇敢，为此，我向你致敬!你对黑铁矮人进行了沉重的打击，如今我们终於有机会将他们彻底赶出我们的国土了……希望这群家伙不再耍什麽花样……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '邪恶的巴尔加拉斯终于死了。他的死无助于挽回那些死在他手中的无辜矮人们，但这至少能安抚那些幸存者们的灵魂。另外，巴尔加拉斯一死，那些苟延残喘的黑铁矮人喽罗们就好对付多了。现在，我们必须在他们找到一位新的领导者之前把他们扫荡干净。$B$B你干得非常出色，$C。$B$B' WHERE `entry` = 304 AND `OfferRewardText_loc4` = '邪恶的巴尔加拉斯终於死了。他的死无助於挽回那些死在他手中的无辜矮人们，但这至少能安抚那些幸存者们的灵魂。另外，巴尔加拉斯一死，那些苟延残喘的黑铁矮人喽罗们就好对付多了。现在，我们必须在他们找到一位新的领导者之前把他们扫荡乾净。$B$B你干得非常出色，$C。$B$B';
