UPDATE `locales_quest` SET `OfferRewardText_loc4` = '塔高尔终于伏法了。俗话说恶有恶报，听到这个消息我真的很高兴。你干得很好，$N。有些时候，真正的正义只有摆脱了法庭的桎梏和政治的腐败才能得到伸张。$B$B' WHERE `entry` = 386 AND `OfferRewardText_loc4` = '塔高尔终於伏法了。俗话说恶有恶报，听到这个消息我真的很高兴。你干得很好，$N。有些时候，真正的正义只有摆脱了法庭的桎梏和政治的腐败才能得到伸张。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你在监狱事件中的表现堪称英勇，$N。显然这个问题对我们来说都不是什么小麻烦。但你干得很出色，我对你非常感激。$B$B' WHERE `entry` = 387 AND `OfferRewardText_loc4` = '你在监狱事件中的表现堪称英勇，$N。显然这个问题对我们来说都不是什麽小麻烦。但你干得很出色，我对你非常感激。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '以圣光之名，你来这儿有什么事?你没看见这儿正乱得一团糟么?$B$B巴基尔·斯瑞德!你为什么想要和这个疯子说话?我怎么知道你们是不是一伙的，如果你是想要来这里帮他挑起暴动的怎么办?要不是因为所有该死的牢房都满了的话，我一定会把你丢进其中一间里去待上一阵!$B$B' WHERE `entry` = 389 AND `OfferRewardText_loc4` = '以圣光之名，你来这儿有什麽事?你没看见这儿正乱得一团糟麽?$B$B巴基尔·斯瑞德!你为什麽想要和这个疯子说话?我怎麽知道你们是不是一夥的，如果你是想要来这里帮他挑起暴动的怎麽办?要不是因为所有该死的牢房都满了的话，我一定会把你丢进其中一间里去待上一阵!$B$B';
