UPDATE `locales_quest` SET `OfferRewardText_loc4` = '他已经死了?你的行动果然很快，$N。圣光保佑，可永远别让我成为你的猎物!$B$B<他大笑并拍着你的肩膀。>$B$B我没别的意思，$N。我怎么可能会有那么一天，我可是所有刺客的首领呢!事实上，你为暴风城的人民做了一件大好事，我要为此谢谢你。$B$B' WHERE `entry` = 394 AND `OfferRewardText_loc4` = '他已经死了?你的行动果然很快，$N。圣光保佑，可永远别让我成为你的猎物!$B$B<他大笑并拍着你的肩膀。>$B$B我没别的意思，$N。我怎麽可能会有那麽一天，我可是所有刺客的首领呢!事实上，你为暴风城的人民做了一件大好事，我要为此谢谢你。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '蛆眼的恶行终于使它得到了应有的下场。或许你英勇的行动会给那些想要伤害我们的家伙一个最明确的警告。我代表布瑞尔镇感谢你的帮助，$N。$B$B' WHERE `entry` = 398 AND `OfferRewardText_loc4` = '蛆眼的恶行终於使它得到了应有的下场。或许你英勇的行动会给那些想要伤害我们的家伙一个最明确的警告。我代表布瑞尔镇感谢你的帮助，$N。$B$B';
