UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你带来了我的工具?干得不错，$G小子:小姑娘;，干得不错!一个小时前，我刚弄坏了最后一个扳手，现在正愁没有工具来修好驾驶员迪恩·石轮的坦克引擎。$N，你可真是帮了我的大忙!请接受这点小小的谢意吧!$B$B' WHERE `entry` = 400 AND `OfferRewardText_loc4` = '你带来了我的工具?干得不错，$G小子:小姑娘;，干得不错!一个小时前，我刚弄坏了最後一个扳手，现在正愁没有工具来修好驾驶员迪恩·石轮的坦克引擎。$N，你可真是帮了我的大忙!请接受这点小小的谢意吧!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得好。我真后悔没能亲眼看见你把那群该死的家伙给捣成烂浆糊!$B$B' WHERE `entry` = 404 AND `OfferRewardText_loc4` = '干得好。我真後悔没能亲眼看见你把那群该死的家伙给捣成烂浆糊!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你的行动对天谴军团来说无疑是次沉重的打击。你的胜利绝对不会被忽视的─无论是对我们被遗忘者还是对天谴军团来说都是这样。$B$B继续尽我们的一切努力来与天谴军团抗争吧，$N，总有那么一天，我们会把巫妖王给赶出艾泽拉斯的!$B$B' WHERE `entry` = 408 AND `OfferRewardText_loc4` = '你的行动对天谴军团来说无疑是次沉重的打击。你的胜利绝对不会被忽视的─无论是对我们被遗忘者还是对天谴军团来说都是这样。$B$B继续尽我们的一切努力来与天谴军团抗争吧，$N，总有那麽一天，我们会把巫妖王给赶出艾泽拉斯的!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你打败了莉莉丝·奈法拉，这充分证明了你确实是天谴军团的敌人，真是令人难以置信呀。$B$B我一直以为我是最后一个拥有独立思想的不死族了，但你已经向我证明了这世上还有其他摆脱了巫妖王统治的不死族。$B$B' WHERE `entry` = 409 AND `OfferRewardText_loc4` = '你打败了莉莉丝·奈法拉，这充分证明了你确实是天谴军团的敌人，真是令人难以置信呀。$B$B我一直以为我是最後一个拥有独立思想的不死族了，但你已经向我证明了这世上还有其他摆脱了巫妖王统治的不死族。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你将诱灵蜡烛放在桌上，然后点燃了它……$B$B' WHERE `entry` = 410 AND `OfferRewardText_loc4` = '你将诱灵蜡烛放在桌上，然後点燃了它……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '让我尝尝……$B$B麦格尼的胡须啊!我觉得天旋地转啦!我的四肢也变得轻飘飘的。$B$B我有一种要飘起来的感觉!$B$B' WHERE `entry` = 414 AND `OfferRewardText_loc4` = '让我嚐嚐……$B$B麦格尼的胡须啊!我觉得天旋地转啦!我的四肢也变得轻飘飘的。$B$B我有一种要飘起来的感觉!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '$N!还记得你带给我的微光草吗?我用它实验了几种酿酒配方，有一种的效果非常好!$B$B品一口看看，然后告诉我，你觉得口味怎么样?$B$B' WHERE `entry` = 415 AND `OfferRewardText_loc4` = '$N!还记得你带给我的微光草吗?我用它实验了几种酿酒配方，有一种的效果非常好!$B$B品一口看看，然後告诉我，你觉得口味怎麽样?$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '呃!没想到这些坑道鼠的耳朵这么难闻!$B$B这是给你的报酬，$N。做得好。$B$B' WHERE `entry` = 416 AND `OfferRewardText_loc4` = '呃!没想到这些坑道鼠的耳朵这麽难闻!$B$B这是给你的报酬，$N。做得好。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这里有一具伤痕累累的矮人尸体，已经完全被冻住了，而且被食腐动物撕咬得不成样子。在它的手里是一本由莫里·铁钻草草写下的日记。这本日记保存得很好，因为它被包在一件坦克驾驶员军用外衣里。$B$B这里一定是那位蒸汽坦克的驾驶员遇难的地方。$B$B' WHERE `entry` = 419 AND `OfferRewardText_loc4` = '这里有一具伤痕累累的矮人屍体，已经完全被冻住了，而且被食腐动物撕咬得不成样子。在它的手里是一本由莫里·铁钻草草写下的日记。这本日记保存得很好，因为它被包在一件坦克驾驶员军用外衣里。$B$B这里一定是那位蒸汽坦克的驾驶员遇难的地方。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这是什么?哦，我兄弟的报告。嗯……$B$B我让他不要动辄就「以国王的名义」，可他就是不听。参议院中肯定会有些家伙对此不满的，不过我想应该没什么大问题，反正他们也从来没有对什么东西满意过，哈哈!$B$B不管怎样，我想我也应该给铁炉堡提交一份报告，不过我承认也许现在有些迟了。这该死的冷天。$B$B如果你有兴趣的话，我有些工作要交给你去做。$B$B' WHERE `entry` = 420 AND `OfferRewardText_loc4` = '这是什麽?哦，我兄弟的报告。嗯……$B$B我让他不要动辄就「以国王的名义」，可他就是不听。参议院中肯定会有些家伙对此不满的，不过我想应该没什麽大问题，反正他们也从来没有对什麽东西满意过，哈哈!$B$B不管怎样，我想我也应该给铁炉堡提交一份报告，不过我承认也许现在有些迟了。这该死的冷天。$B$B如果你有兴趣的话，我有些工作要交给你去做。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这正是我正要找的法术，$C。如果你在以后为黑暗女士效力的过程中仍能像现在这样干净俐落的话，你无疑会在被遗忘者中拥有一个美好的未来。$B$B' WHERE `entry` = 422 AND `OfferRewardText_loc4` = '这正是我正要找的法术，$C。如果你在以後为黑暗女士效力的过程中仍能像现在这样乾净俐落的话，你无疑会在被遗忘者中拥有一个美好的未来。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '嗯，你终于让我感觉好些了……$B$B但是，只要它们还有一个活着，我就高兴不起来!它们全都得去死!$B$B' WHERE `entry` = 432 AND `OfferRewardText_loc4` = '嗯，你终於让我感觉好些了……$B$B但是，只要它们还有一个活着，我就高兴不起来!它们全都得去死!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这只是个开始。希望我们能利用这段时间，赶紧去找一些巡山人来保护这个地区。然后我们就可以开始重建基础设施，让矿工们回来工作。$B$B谢谢你的帮助，$N。$B$B' WHERE `entry` = 433 AND `OfferRewardText_loc4` = '这只是个开始。希望我们能利用这段时间，赶紧去找一些巡山人来保护这个地区。然後我们就可以开始重建基础设施，让矿工们回来工作。$B$B谢谢你的帮助，$N。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '任务完成了?很好。非常感谢你，$N。你已经完全证明了自己的价值。我会时刻关注你的进步。$B$B以后你行事最好也像这次一样干净俐落。$B$B' WHERE `entry` = 434 AND `OfferRewardText_loc4` = '任务完成了?很好。非常感谢你，$N。你已经完全证明了自己的价值。我会时刻关注你的进步。$B$B以後你行事最好也像这次一样乾净俐落。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '吉恩想知道为什么进展缓慢，是吗?铁环已经把最近的情况写进了一份详细报告里，不过我可以简单地告诉你:$B$B是穴居人在作祟!!$B$B' WHERE `entry` = 436 AND `OfferRewardText_loc4` = '吉恩想知道为什麽进展缓慢，是吗?铁环已经把最近的情况写进了一份详细报告里，不过我可以简单地告诉你:$B$B是穴居人在作祟!!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这艘小船中装满了尸体。你抬头向东边看去，发现在洛丹米尔湖中央的芬里斯岛上也有一个码头。$B$B这些尸体应该是要被运到芬里斯岛上去的。$B$B' WHERE `entry` = 438 AND `OfferRewardText_loc4` = '这艘小船中装满了屍体。你抬头向东边看去，发现在洛丹米尔湖中央的芬里斯岛上也有一个码头。$B$B这些屍体应该是要被运到芬里斯岛上去的。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你说这个戒指是在一个可能是刚被杀的女人身上找到的。$B$B那附近唯一可能有尸体的地方只能是提里斯法的公墓了。腐皮豺狼人一定是将尸体拖到芬里斯岛去了!$B$B' WHERE `entry` = 439 AND `OfferRewardText_loc4` = '你说这个戒指是在一个可能是刚被杀的女人身上找到的。$B$B那附近唯一可能有屍体的地方只能是提里斯法的公墓了。腐皮豺狼人一定是将屍体拖到芬里斯岛去了!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '不久前这里是住过一个叫黛丽娅的。她应该被葬在公墓里，不过，如果你说的是真的，她的尸体或许已经被腐皮豺狼人偷走带去银松森林了。$B$B那群腐皮豺狼人跟天谴军团一样，一定要被彻底消灭。我相信你所做的事情会帮我们最终实现这个目标。$B$B' WHERE `entry` = 440 AND `OfferRewardText_loc4` = '不久前这里是住过一个叫黛丽娅的。她应该被葬在公墓里，不过，如果你说的是真的，她的屍体或许已经被腐皮豺狼人偷走带去银松森林了。$B$B那群腐皮豺狼人跟天谴军团一样，一定要被彻底消灭。我相信你所做的事情会帮我们最终实现这个目标。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '是的，这正是我妻子的戒指。她的命运，和那些所有没能忍耐着度过这段艰难时世的人一样。我对她的死没有什么想法，她的尸体失踪了又怎样。$B$B我早就丧失了这些多余的情感了。但复仇的欲望却仍在我已死的心中燃烧着，$N。$B$B' WHERE `entry` = 441 AND `OfferRewardText_loc4` = '是的，这正是我妻子的戒指。她的命运，和那些所有没能忍耐着度过这段艰难时世的人一样。我对她的死没有什麽想法，她的屍体失踪了又怎样。$B$B我早就丧失了这些多余的情感了。但复仇的欲望却仍在我已死的心中燃烧着，$N。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，乔汉送来了他的报告，太好了。由于银松森林这边发生的事情实在是太多了，我几乎把罗德隆巴提里斯法林地那边来的报告都全丢在了一边。这倒提醒了我，我得把这些来自各地的样本赶紧送到大墓地去。$B$B但你恐怕得先在这里待一段时间，替我做点跑腿打杂的事。好好在银松森林里见识见识吧，$N。我们这儿用得着像你这样能干的$C。$B$B' WHERE `entry` = 445 AND `OfferRewardText_loc4` = '啊，乔汉送来了他的报告，太好了。由於银松森林这边发生的事情实在是太多了，我几乎把罗德隆巴提里斯法林地那边来的报告都全丢在了一边。这倒提醒了我，我得把这些来自各地的样本赶紧送到大墓地去。$B$B但你恐怕得先在这里待一段时间，替我做点跑腿打杂的事。好好在银松森林里见识见识吧，$N。我们这儿用得着像你这样能干的$C。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '如果比索说的是真的，那么图勒·鸦爪恐怕真是一个不容我们忽视的家伙了，我们得尽快把他消灭掉。$B$B为了帮助你完成好这个任务，你可以从我们的军械库里拿些东西。$B$B' WHERE `entry` = 448 AND `OfferRewardText_loc4` = '如果比索说的是真的，那麽图勒·鸦爪恐怕真是一个不容我们忽视的家伙了，我们得尽快把他消灭掉。$B$B为了帮助你完成好这个任务，你可以从我们的军械库里拿些东西。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '伯纳德的日记!你真是太勇敢了，$N。现在让我看看伯纳德在疯掉之前都做了些什么……$B$B' WHERE `entry` = 450 AND `OfferRewardText_loc4` = '伯纳德的日记!你真是太勇敢了，$N。现在让我看看伯纳德在疯掉之前都做了些什麽……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '皇家药剂师学会失去了博拉尔德实在是太可惜了。但通过你的努力，还有药剂师伦弗利尔对博拉尔德留下的东西的详细研究，我们仍然能为黑暗女士帮忙。$B$B我们正在做一件伟大的事业，$N。如果你不是那么擅长作战就好了，那样的话，我一定会举荐你进入学会的。$B$B' WHERE `entry` = 451 AND `OfferRewardText_loc4` = '皇家药剂师学会失去了博拉尔德实在是太可惜了。但通过你的努力，还有药剂师伦弗利尔对博拉尔德留下的东西的详细研究，我们仍然能为黑暗女士帮忙。$B$B我们正在做一件伟大的事业，$N。如果你不是那麽擅长作战就好了，那样的话，我一定会举荐你进入学会的。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<基特斯叹了口气>$B$B是的，我就是那本书的作者。你终于找到我了么……$B$B如果你读了那本日记的话…你只了解到了事实的一半!$B$B' WHERE `entry` = 453 AND `OfferRewardText_loc4` = '<基特斯叹了口气>$B$B是的，我就是那本书的作者。你终於找到我了麽……$B$B如果你读了那本日记的话…你只了解到了事实的一半!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你的报告里怎么全都是些坏消息!$B$B我觉得那些龙喉兽人们一定是想向奥加兹推进。过去龙喉氏族一直是躲在深山里，从不与外界接触。到底是什么迫使他们要进入奥加兹，这就不得而知了……$B$B谢谢你，$N。我们可能还会需要你来帮忙对付那些兽人。$B$B' WHERE `entry` = 455 AND `OfferRewardText_loc4` = '你的报告里怎麽全都是些坏消息!$B$B我觉得那些龙喉兽人们一定是想向奥加兹推进。过去龙喉氏族一直是躲在深山里，从不与外界接触。到底是什麽迫使他们要进入奥加兹，这就不得而知了……$B$B谢谢你，$N。我们可能还会需要你来帮忙对付那些兽人。$B$B';
