UPDATE `locales_quest` SET `OfferRewardText_loc4` = '嗯……如果你有兴趣当我的学徒的话，就跟着我混吧，如何?$B$B哈!别怕别怕，开个小玩笑么。你来当我的学徒的话，年纪大了点。不过，你打来的这些皮不错，我会好好利用的。$B$B' WHERE `entry` = 471 AND `OfferRewardText_loc4` = '嗯……如果你有兴趣当我的学徒的话，就跟着我混吧，如何?$B$B哈!别怕别怕，开个小玩笑麽。你来当我的学徒的话，年纪大了点。不过，你打来的这些皮不错，我会好好利用的。$B$B';
