UPDATE `locales_quest` SET `OfferRewardText_loc4` = '感谢森林之灵，终于有人来了!我知道阿斯瑞达斯会感觉到这里有了麻烦，而且会及时伸出援助之手……$B$B' WHERE `entry` = 475 AND `OfferRewardText_loc4` = '感谢森林之灵，终於有人来了!我知道阿斯瑞达斯会感觉到这里有了麻烦，而且会及时伸出援助之手……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<小心地打开了木箱盖之后，你发现了一些摆放整齐的东西，它们都被仔细地包裹着。最上面是一捆地图，因为年代久远，纸张已经有些泛黄了，这些地图绘制的是银松森林一带，以及西罗德隆的其他一些地区。$B$B地图的下面则是一个神秘的魔法坠饰。>$B$B' WHERE `entry` = 477 AND `OfferRewardText_loc4` = '<小心地打开了木箱盖之後，你发现了一些摆放整齐的东西，它们都被仔细地包裹着。最上面是一捆地图，因为年代久远，纸张已经有些泛黄了，这些地图绘制的是银松森林一带，以及西罗德隆的其他一些地区。$B$B地图的下面则是一个神秘的魔法坠饰。>$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '地图和这个……坠饰，就这些吗?真有趣。$B$B显然达拉然的巫师们一直待在安伯米尔是有些原因的，但是现在我还是不知道他们到底要做些什么。$B$B或许达拉尔知道些什么。$B$B' WHERE `entry` = 478 AND `OfferRewardText_loc4` = '地图和这个……坠饰，就这些吗?真有趣。$B$B显然达拉然的巫师们一直待在安伯米尔是有些原因的，但是现在我还是不知道他们到底要做些什麽。$B$B或许达拉尔知道些什麽。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '尽管已经失败了好几次，但达拉尔还是发现了一个位于很远处的地方有着强大的魔法波动。$B$B某个强大的巫师正在那里引导着魔法能量，我们必须马上阻止他。$B$B' WHERE `entry` = 479 AND `OfferRewardText_loc4` = '尽管已经失败了好几次，但达拉尔还是发现了一个位於很远处的地方有着强大的魔法波动。$B$B某个强大的巫师正在那里引导着魔法能量，我们必须马上阻止他。$B$B';
