UPDATE `locales_quest` SET `OfferRewardText_loc4` = '人类想要把我们的战士变成奴隶，不是吗?我们得给他们点颜色看看!$B$B看起来他们好像把我们的首领高迪尔转移到别的地方去了。我们必须把他救出来!不过现在我们还不知道他被关押在什么地方……$B$B一旦有了线索，我们一定会在第一时间告诉你的，$N。$B$B' WHERE `entry` = 498 AND `OfferRewardText_loc4` = '人类想要把我们的战士变成奴隶，不是吗?我们得给他们点颜色看看!$B$B看起来他们好像把我们的首领高迪尔转移到别的地方去了。我们必须把他救出来!不过现在我们还不知道他被关押在什麽地方……$B$B一旦有了线索，我们一定会在第一时间告诉你的，$N。$B$B';
