UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<马雷布查看了合约。>$B$B这份契约终于让最近频频发生在南海镇的袭击事件有了眉目。辛迪加一定是针对我，就像他们针对前一任镇长那样!$B$B' WHERE `entry` = 522 AND `OfferRewardText_loc4` = '<马雷布查看了合约。>$B$B这份契约终於让最近频频发生在南海镇的袭击事件有了眉目。辛迪加一定是针对我，就像他们针对前一任镇长那样!$B$B';
