UPDATE `locales_quest` SET `OfferRewardText_loc4` = '终于知道高迪尔被关在哪里了。我们怀疑关押他的营地离这儿不远，而且这次他们很有可能不像上次抓我们时准备得那么充分。$B$B' WHERE `entry` = 533 AND `OfferRewardText_loc4` = '终於知道高迪尔被关在哪里了。我们怀疑关押他的营地离这儿不远，而且这次他们很有可能不像上次抓我们时准备得那麽充分。$B$B';
