UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我希望这样就可以让雷德帕斯完全相信我已经─哈哈─完成了他的命令，为南海镇除去了可怕的鱼人!没有什么比那些畸形的大鱼更邪恶的了!$B$B' WHERE `entry` = 536 AND `OfferRewardText_loc4` = '我希望这样就可以让雷德帕斯完全相信我已经─哈哈─完成了他的命令，为南海镇除去了可怕的鱼人!没有什麽比那些畸形的大鱼更邪恶的了!$B$B';
