UPDATE `locales_quest` SET `OfferRewardText_loc4` = '好极了!谢谢你的帮忙，我现在可以完成这笔订单，然后在下次运货的时候把它寄给地下矿坑的主管雷德沃克斯。甚至还可以提早给他!$B$B为了对你的帮助表示感谢，我特别为你多做了一双，拿着吧。是我崔斯里克送你的。$B$B记住，没什么靴子比崔斯里克的雕花皮靴更完美了!$B$B' WHERE `entry` = 628 AND `OfferRewardText_loc4` = '好极了!谢谢你的帮忙，我现在可以完成这笔订单，然後在下次运货的时候把它寄给地下矿坑的主管雷德沃克斯。甚至还可以提早给他!$B$B为了对你的帮助表示感谢，我特别为你多做了一双，拿着吧。是我崔斯里克送你的。$B$B记住，没什麽靴子比崔斯里克的雕花皮靴更完美了!$B$B';
