UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，你是说戈莫尔啊。没错，看来他依然无法从对末日锤战死的悲伤中恢复过来。$B$B当索尔和奥格瑞姆为解放这里作战的时候，戈莫尔正是这里的俘虏。但当大地开始震动，我们向外逃离这里的时候，他却落单了。他漫无目的、毫无方向地一个人独自游荡了很多年，直到我们来到落锤村并在这里建立了属于自己的家园。$B$B' WHERE `entry` = 655 AND `OfferRewardText_loc4` = '啊，你是说戈莫尔啊。没错，看来他依然无法从对末日锤战死的悲伤中恢复过来。$B$B当索尔和奥格瑞姆为解放这里作战的时候，戈莫尔正是这里的俘虏。但当大地开始震动，我们向外逃离这里的时候，他却落单了。他漫无目的、毫无方向地一个人独自游荡了很多年，直到我们来到落锤村并在这里建立了属於自己的家园。$B$B';
