UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你帮了我们的大忙，$N，谢谢你。$B$B但愿基恩洛刚才的凶狠善战没有吓到你。她对朋友很和善，但是对于敌人，她决不会有半点怜悯之心。$B$B' WHERE `entry` = 660 AND `OfferRewardText_loc4` = '你帮了我们的大忙，$N，谢谢你。$B$B但愿基恩洛刚才的凶狠善战没有吓到你。她对朋友很和善，但是对於敌人，她决不会有半点怜悯之心。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '那么，这两个捣蛋鬼都没什么事罗?哈哈，我很高兴听到这个消息。谢谢你告诉我有关她们的消息—我很高兴她们还活着。她们俩是我不可缺少的朋友和旅伴。$B$B可是……我衷心地感谢你的帮助，拿着这个吧。$B$B如果运气好的话，我们就能查出那些被遗忘者到底要做些什么，并及时地阻止他们。$B$B' WHERE `entry` = 661 AND `OfferRewardText_loc4` = '那麽，这两个捣蛋鬼都没什麽事罗?哈哈，我很高兴听到这个消息。谢谢你告诉我有关她们的消息—我很高兴她们还活着。她们俩是我不可缺少的朋友和旅伴。$B$B可是……我衷心地感谢你的帮助，拿着这个吧。$B$B如果运气好的话，我们就能查出那些被遗忘者到底要做些什麽，并及时地阻止他们。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '嘿，伙计。$B$B这真是乱得一塌糊涂。如果海角大人发现我这里的状况的话，他一准会没收我所有的船只。$B$B教授的装置显示丢失的宝藏就在海湾附近。我把先驱号开到码头，然后向银松之灵号和处女号发出请跟随的信号。$B$B突然之间大海隆隆作响，海浪将那两艘可怜的船卷向了暗礁。$B$B那里不止是片暗礁，而且还潜藏着别的东西……$B$B帮我把我的船员救出来吧，我发誓你会得到一笔丰厚的奖励。$B$B' WHERE `entry` = 663 AND `OfferRewardText_loc4` = '嘿，夥计。$B$B这真是乱得一塌糊涂。如果海角大人发现我这里的状况的话，他一准会没收我所有的船只。$B$B教授的装置显示丢失的宝藏就在海湾附近。我把先驱号开到码头，然後向银松之灵号和处女号发出请跟随的信号。$B$B突然之间大海隆隆作响，海浪将那两艘可怜的船卷向了暗礁。$B$B那里不止是片暗礁，而且还潜藏着别的东西……$B$B帮我把我的船员救出来吧，我发誓你会得到一笔丰厚的奖励。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得漂亮，$N。那些混帐东西罪有应得。既然我的船和我的水手们已经不在了，那么就让这些纳迦的死给我带来一些安慰吧。$B$B' WHERE `entry` = 664 AND `OfferRewardText_loc4` = '干得漂亮，$N。那些混帐东西罪有应得。既然我的船和我的水手们已经不在了，那麽就让这些纳迦的死给我带来一些安慰吧。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '摧毁了这颗宝珠之后，我终于能从那一个个不眠之夜中摆脱出来，安安稳稳地睡几个好觉了。谢谢你，$N。这颗宝珠让我想起了兽人被恶魔的黑暗力量所统治的那段时间，最终还是葛罗·地狱吼让我们从诅咒中解脱了。$B$B' WHERE `entry` = 673 AND `OfferRewardText_loc4` = '摧毁了这颗宝珠之後，我终於能从那一个个不眠之夜中摆脱出来，安安稳稳地睡几个好觉了。谢谢你，$N。这颗宝珠让我想起了兽人被恶魔的黑暗力量所统治的那段时间，最终还是葛罗·地狱吼让我们从诅咒中解脱了。$B$B';
