UPDATE `locales_quest` SET `OfferRewardText_loc4` = '$N，你考虑过要当我的研究助理吗?没有?如果没有你的协助，我都不知道能做些什么了。智慧，好奇心和力量─你拥有这所有的一切。$B$B' WHERE `entry` = 712 AND `OfferRewardText_loc4` = '$N，你考虑过要当我的研究助理吗?没有?如果没有你的协助，我都不知道能做些什麽了。智慧，好奇心和力量─你拥有这所有的一切。$B$B';
