UPDATE `locales_quest` SET `OfferRewardText_loc4` = '哦!这件事可不属于无聊的问题之列。你可能还没有意识到这件事的严重性，对吗?$B$B我对铁趾的去世感到很痛心，不过既然他让你拿来护符，就说明他了解事情有多么的危急。$B$B我们现在没有时间对铁趾进行哀悼了。$B$B让我告诉你这枚护符的价值所在吧。$B$B' WHERE `entry` = 724 AND `OfferRewardText_loc4` = '哦!这件事可不属於无聊的问题之列。你可能还没有意识到这件事的严重性，对吗?$B$B我对铁趾的去世感到很痛心，不过既然他让你拿来护符，就说明他了解事情有多麽的危急。$B$B我们现在没有时间对铁趾进行哀悼了。$B$B让我告诉你这枚护符的价值所在吧。$B$B';
