UPDATE `locales_quest` SET `OfferRewardText_loc4` = '$N，谢谢你救了我一命。$B$B请收下这个，即使它一文不值，我也希望它能对你有所帮助。看样子我近期应该是用不上它了。在我重新证明自己之前，考格汉只会让我去做些例行的公事，比如杀杀野猪、找找蝎尾什么的……<他叹了一口气>$B$B' WHERE `entry` = 812 AND `OfferRewardText_loc4` = '$N，谢谢你救了我一命。$B$B请收下这个，即使它一文不值，我也希望它能对你有所帮助。看样子我近期应该是用不上它了。在我重新证明自己之前，考格汉只会让我去做些例行的公事，比如杀杀野猪、找找蠍尾什麽的……<他叹了一口气>$B$B';
