UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<他仔细地检查着燃影之眼>$B$B有意思。你听到的那个声音提到我的名字?我为酋长和部落猎杀敌人的事情是众所周知的，不过奇怪的是……他为什么会特别提到我。此外持有这个饰物的火刃祭司的名字怎么和我的名字如此相像?$B$B我得研究一下这个饰物，看看它到底隐藏着什么秘密。$B$B谢谢你把这个东西交给我，$N。你为我们的同胞作出了巨大的贡献。$B$B' WHERE `entry` = 832 AND `OfferRewardText_loc4` = '<他仔细地检查着燃影之眼>$B$B有意思。你听到的那个声音提到我的名字?我为酋长和部落猎杀敌人的事情是众所周知的，不过奇怪的是……他为什麽会特别提到我。此外持有这个饰物的火刃祭司的名字怎麽和我的名字如此相像?$B$B我得研究一下这个饰物，看看它到底隐藏着什麽秘密。$B$B谢谢你把这个东西交给我，$N。你为我们的同胞作出了巨大的贡献。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我想我终于可以歇口气了，鹰身人再也没法袭击我们的商队了，至少短时间内如此。听说下一批货物中还有些有趣的玩意!$B$B你干得很好，$N，你可以去棘齿城找我的老板 加兹鲁维。我敢说他会给你找点事做的。$B$B哦，别担心，我不会忘了付你报酬的。$B$B' WHERE `entry` = 835 AND `OfferRewardText_loc4` = '我想我终於可以歇口气了，鹰身人再也没法袭击我们的商队了，至少短时间内如此。听说下一批货物中还有些有趣的玩意!$B$B你干得很好，$N，你可以去棘齿城找我的老板 加兹鲁维。我敢说他会给你找点事做的。$B$B哦，别担心，我不会忘了付你报酬的。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我会让大家都知道野猪人已经被赶出他们的老巢，他们的结构会出现大乱。从杜洛塔赶走了钢鬃野猪人之后，我们的边境就更加安全了。$B$B' WHERE `entry` = 837 AND `OfferRewardText_loc4` = '我会让大家都知道野猪人已经被赶出他们的老巢，他们的结构会出现大乱。从杜洛塔赶走了钢鬃野猪人之後，我们的边境就更加安全了。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '哦，是塔克林让你来的?他是个出色的斥候，没他我还真不知道该怎么办呢。$B$B我会在你的募兵信上签字，不过真正需要人手的地方是十字路口，不是我这里。$B$B' WHERE `entry` = 840 AND `OfferRewardText_loc4` = '哦，是塔克林让你来的?他是个出色的斥候，没他我还真不知道该怎麽办呢。$B$B我会在你的募兵信上签字，不过真正需要人手的地方是十字路口，不是我这里。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '卡兹戈姆罪有应得，我对这个白痴的下场不会有丝毫的同情。他根本不属于这片土地。$B$B希望他的死能警告所有那些对我们的生活构成威胁的人。$B$B现在，让我来研究一下这个矮人的日记……$B$B' WHERE `entry` = 843 AND `OfferRewardText_loc4` = '卡兹戈姆罪有应得，我对这个白痴的下场不会有丝毫的同情。他根本不属於这片土地。$B$B希望他的死能警告所有那些对我们的生活构成威胁的人。$B$B现在，让我来研究一下这个矮人的日记……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '当那宝珠上的魔法退去之后，我会和戈莫尔谈谈的。感谢你帮助戈莫尔返回了这片充满生机的土地，我确信他也会非常感谢你的。$B$B' WHERE `entry` = 847 AND `OfferRewardText_loc4` = '当那宝珠上的魔法退去之後，我会和戈莫尔谈谈的。感谢你帮助戈莫尔返回了这片充满生机的土地，我确信他也会非常感谢你的。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得漂亮。我想你已经让那些苟活的半人马感受到了恐惧，$N。如果他们还有些理智的话，现在就应该冷静下来，停止他们的行动。$B$B但我恐怕他们不会那么做，真糟糕。$B$B这个糟糕……是对他们而言的。$B$B' WHERE `entry` = 855 AND `OfferRewardText_loc4` = '干得漂亮。我想你已经让那些苟活的半人马感受到了恐惧，$N。如果他们还有些理智的话，现在就应该冷静下来，停止他们的行动。$B$B但我恐怕他们不会那麽做，真糟糕。$B$B这个糟糕……是对他们而言的。$B$B';
