UPDATE `locales_quest` SET `OfferRewardText_loc4` = '控制台的表面凌乱地布满了众多的按钮、控制杆和不断闪烁的指示灯。一部小型仪表显示这台设备正处于最佳的工作状态下，一至三号控制阀门已经打开。在控制面板的右下方有一个插钥匙的小孔。$B$B' WHERE `entry` = 894 AND `OfferRewardText_loc4` = '控制台的表面淩乱地布满了众多的按钮、控制杆和不断闪烁的指示灯。一部小型仪表显示这台设备正处於最佳的工作状态下，一至三号控制阀门已经打开。在控制面板的右下方有一个插钥匙的小孔。$B$B';
