UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我无法判断这是什么生物，因为它的灵魂已经消散。不过，正如你猜测的那样，它并不属于贫瘠之地。我担心它可能会为我们的同胞带来灾难……$B$B现在，做好准备，让我们一起期待揭开这种生物的谜团的那一天吧。$B$B' WHERE `entry` = 897 AND `OfferRewardText_loc4` = '我无法判断这是什麽生物，因为它的灵魂已经消散。不过，正如你猜测的那样，它并不属於贫瘠之地。我担心它可能会为我们的同胞带来灾难……$B$B现在，做好准备，让我们一起期待揭开这种生物的谜团的那一天吧。$B$B';
