UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你重造了魔棒?听到这样的好消息真是太让人高兴了。$B$B如果泰洛尼斯知道他的使命终于得以完成了的话，他也会为你感到欣慰的。$B$B' WHERE `entry` = 1029 AND `OfferRewardText_loc4` = '你重造了魔棒?听到这样的好消息真是太让人高兴了。$B$B如果泰洛尼斯知道他的使命终於得以完成了的话，他也会为你感到欣慰的。$B$B';
