UPDATE `locales_quest` SET `OfferRewardText_loc4` = '由于这几年我们这儿发生的怪事越来越多，所以我就保留了所有出入过这里的陌生人的记录。虽然这不是个令人愉快的活儿，但谁又能知道这些东西什么时候就会派上大用场呢?不过……很抱歉，我这里似乎没有你要找的那个维琳德的任何资料。$B$B' WHERE `entry` = 1041 AND `OfferRewardText_loc4` = '由於这几年我们这儿发生的怪事越来越多，所以我就保留了所有出入过这里的陌生人的记录。虽然这不是个令人愉快的活儿，但谁又能知道这些东西什麽时候就会派上大用场呢?不过……很抱歉，我这里似乎没有你要找的那个维琳德的任何资料。$B$B';
