UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊~~~我就知道，让匹兹尼克待在那里面打探消息是再正确不过了。我敢打赌安德麦那边的工程师们一定会对这东西感兴趣的……$B$B当然我会给自己留下一小块，这对他们应该没有什么影响，对吧?$B$B' WHERE `entry` = 1092 AND `OfferRewardText_loc4` = '啊~~~我就知道，让匹兹尼克待在那里面打探消息是再正确不过了。我敢打赌安德麦那边的工程师们一定会对这东西感兴趣的……$B$B当然我会给自己留下一小块，这对他们应该没有什麽影响，对吧?$B$B';
