UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这……这是什么?$B$B它的样子……像个盒子，对吗?这里面有一些有趣的东西。等等，有一部份是打开着的……怎么会有一本书?$B$B我想你发现的还是很有用的，$N……好吧，至少我希望如此。也许它是一本被封在这个外壳里面的古代日记。$B$B我想我有办法知道它究竟是什么。$B$B' WHERE `entry` = 1126 AND `OfferRewardText_loc4` = '这……这是什麽?$B$B它的样子……像个盒子，对吗?这里面有一些有趣的东西。等等，有一部份是打开着的……怎麽会有一本书?$B$B我想你发现的还是很有用的，$N……好吧，至少我希望如此。也许它是一本被封在这个外壳里面的古代日记。$B$B我想我有办法知道它究竟是什麽。$B$B';
