UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你好!是米奈希尔港的弗林特先生派你来的吗?弗林特先生从来就不会看错人的。如果是他派你来的，那么我坚信你就是那个命中注定要在卡林多做出一番事业的$R。$B$B' WHERE `entry` = 1132 AND `OfferRewardText_loc4` = '你好!是米奈希尔港的弗林特先生派你来的吗?弗林特先生从来就不会看错人的。如果是他派你来的，那麽我坚信你就是那个命中注定要在卡林多做出一番事业的$R。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '$N，能打败霜喉雪人就证明你有着过人的力量和机智。$B$B现在你已经去过了千针石林大峡谷和奥特兰克山，将来你一定会走遍世界，因为这是一条属于猎人的命运之路。$B$B' WHERE `entry` = 1136 AND `OfferRewardText_loc4` = '$N，能打败霜喉雪人就证明你有着过人的力量和机智。$B$B现在你已经去过了千针石林大峡谷和奥特兰克山，将来你一定会走遍世界，因为这是一条属於猎人的命运之路。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '$N，你回来啦!你找到马特克了吗?你和他谈过了吗?他说了些什么?他能帮忙吗??$B$B告诉我告诉我告诉我!!$B$B' WHERE `entry` = 1137 AND `OfferRewardText_loc4` = '$N，你回来啦!你找到马特克了吗?你和他谈过了吗?他说了些什麽?他能帮忙吗??$B$B告诉我告诉我告诉我!!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啧啧，这些螃蟹肉正是我要的。谢谢你，$N!我在钓鱼的时候发现了这个，它对我来说没有什么用，也许它对你来说还有点用处，当然你没法用它做出螃蟹大餐来。$B$B我已经把所有关于螃蟹的东西都告诉你了，是不是?$B$B' WHERE `entry` = 1138 AND `OfferRewardText_loc4` = '啧啧，这些螃蟹肉正是我要的。谢谢你，$N!我在钓鱼的时候发现了这个，它对我来说没有什麽用，也许它对你来说还有点用处，当然你没法用它做出螃蟹大餐来。$B$B我已经把所有关於螃蟹的东西都告诉你了，是不是?$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我希望埃瑟里克斯的死能够帮助我们击退这个地区的恶魔势力。毫无疑问，他们还会重新集结然后卷土重来，不过到那个时候，我们就会有更加充分的准备。$B$B' WHERE `entry` = 1143 AND `OfferRewardText_loc4` = '我希望埃瑟里克斯的死能够帮助我们击退这个地区的恶魔势力。毫无疑问，他们还会重新集结然後卷土重来，不过到那个时候，我们就会有更加充分的准备。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，科兰的信。他一直以来都是个忠实的仆人，我刚才还在想着他在十字路口干得怎么样了呢。$B$B' WHERE `entry` = 1145 AND `OfferRewardText_loc4` = '啊，科兰的信。他一直以来都是个忠实的仆人，我刚才还在想着他在十字路口干得怎麽样了呢。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，你最近见过摩克塔?他总是很照顾我。很遗憾听说他不得不把时间都花在他的小队身上，而不能亲历千军万马的战场，但是对他来说，只要能有机会干掉那么几个探险联盟的成员就足够开心了。$B$B谢谢你把这些昆虫带给我，$N。结合在巨人旷野发现的虫卵，我们应该可以对这些昆虫究竟是什么以及它们抱有怎样的目的有一个大概的了解。$B$B' WHERE `entry` = 1148 AND `OfferRewardText_loc4` = '啊，你最近见过摩克塔?他总是很照顾我。很遗憾听说他不得不把时间都花在他的小队身上，而不能亲历千军万马的战场，但是对他来说，只要能有机会干掉那麽几个探险联盟的成员就足够开心了。$B$B谢谢你把这些昆虫带给我，$N。结合在巨人旷野发现的虫卵，我们应该可以对这些昆虫究竟是什麽以及它们抱有怎样的目的有一个大概的了解。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我们只有在面临不可预见的灾祸时才能发现自己的精神到底能有多么强大。在不知道自己是否能够存活的情况下，你为了信仰纵身一跳。你的思想已经得到了升华，你的精神已准备就绪。$B$B如果你愿意，那就准备迎接你的第二个试炼吧。$B$B' WHERE `entry` = 1149 AND `OfferRewardText_loc4` = '我们只有在面临不可预见的灾祸时才能发现自己的精神到底能有多麽强大。在不知道自己是否能够存活的情况下，你为了信仰纵身一跳。你的思想已经得到了昇华，你的精神已准备就绪。$B$B如果你愿意，那就准备迎接你的第二个试炼吧。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '力量试炼完成了。你显示了你的力量和勇气，看来你已经为最后的试炼做好了准备。$B$B' WHERE `entry` = 1151 AND `OfferRewardText_loc4` = '力量试炼完成了。你显示了你的力量和勇气，看来你已经为最後的试炼做好了准备。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你是代表着复仇信念的$C，我要对你鞠躬以表示感谢。$B$B既然那母牛已经死了，她的野种也不会再在艾泽拉斯大陆上出现了，这样我就可以把我的全部精力投入到一些对自己更有利的事情中。你把她们都给结果了以后没忘记搜搜那个农场吧?$B$B' WHERE `entry` = 1164 AND `OfferRewardText_loc4` = '你是代表着复仇信念的$C，我要对你鞠躬以表示感谢。$B$B既然那母牛已经死了，她的野种也不会再在艾泽拉斯大陆上出现了，这样我就可以把我的全部精力投入到一些对自己更有利的事情中。你把她们都给结果了以後没忘记搜搜那个农场吧?$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，真高兴我们又见面了，$N。这里刚刚发生了一件非常奇怪的事情，你来的真是时候!$B$B这真是太奇怪了，$N。一切似乎都很正常─就像现在这周围一样平淡无奇─突然，从塔顶的一间小屋里发出了令人眩目的强光，紧接着传出了一阵尖叫。那尖叫声刺破了夜空，时断时续的强光照亮了大地。究竟发生了什么呢?$B$B' WHERE `entry` = 1167 AND `OfferRewardText_loc4` = '啊，真高兴我们又见面了，$N。这里刚刚发生了一件非常奇怪的事情，你来的真是时候!$B$B这真是太奇怪了，$N。一切似乎都很正常─就像现在这周围一样平淡无奇─突然，从塔顶的一间小屋里发出了令人眩目的强光，紧接着传出了一阵尖叫。那尖叫声刺破了夜空，时断时续的强光照亮了大地。究竟发生了什麽呢?$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '那个懒惰的懦夫!$B$B雷克萨还是我们领袖的时候，莫格穆洛克还挺有能力的，谁知道雷克萨一走，他就成了权力的奴仆!他不再领导我们，而是不断要求我们;他不再为他的人民服务，而是要其他人为他服务。$B$B我们一定得做点什么才行。$B$B' WHERE `entry` = 1171 AND `OfferRewardText_loc4` = '那个懒惰的懦夫!$B$B雷克萨还是我们领袖的时候，莫格穆洛克还挺有能力的，谁知道雷克萨一走，他就成了权力的奴仆!他不再领导我们，而是不断要求我们;他不再为他的人民服务，而是要其他人为他服务。$B$B我们一定得做点什麽才行。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '太出色了!奥妮克希亚还得再等一段时间才能产出更多卵来。$B$B我代表我的族人感谢你，$N。$B$B我已经要求你做了太多，不过你还可以为石槌氏族做最后一件事。$B$B莫格穆洛克不适合领导我们，而萨尔格却是个出色的领袖，只不过因为年纪和伤痛而无法胜任。用武力把莫格穆洛克从这儿赶出去吧，只有这样我们才能选出一个新领袖，带领我们重返南方的家园。$B$B' WHERE `entry` = 1172 AND `OfferRewardText_loc4` = '太出色了!奥妮克希亚还得再等一段时间才能产出更多卵来。$B$B我代表我的族人感谢你，$N。$B$B我已经要求你做了太多，不过你还可以为石槌氏族做最後一件事。$B$B莫格穆洛克不适合领导我们，而萨尔格却是个出色的领袖，只不过因为年纪和伤痛而无法胜任。用武力把莫格穆洛克从这儿赶出去吧，只有这样我们才能选出一个新领袖，带领我们重返南方的家园。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我希望你没有把那些跑进赛道的蜥蜴给干掉!它们的尸体在太阳下需要很长时间才能腐烂，到时候还要我一铲一铲地清理干净。$B$B' WHERE `entry` = 1175 AND `OfferRewardText_loc4` = '我希望你没有把那些跑进赛道的蜥蜴给干掉!它们的屍体在太阳下需要很长时间才能腐烂，到时候还要我一铲一铲地清理乾净。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '太好了!这些部件终于让我可以开始工作了。$N，谢谢你!$B$B' WHERE `entry` = 1176 AND `OfferRewardText_loc4` = '太好了!这些部件终於让我可以开始工作了。$N，谢谢你!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '普兹克派你来的，是吗?你要知道，在普兹克退休去为车队工作之前，他是安德麦最令人尊敬的工匠之一。$B$B他加入赛车队后的第一件事就是开发了双引擎赛车。如果他没有为技工协会工作过，这些事儿就不会那么顺畅了，但谁会关心这个呢，对吧?再没有比赛车更让人关心的啦!$B$B' WHERE `entry` = 1178 AND `OfferRewardText_loc4` = '普兹克派你来的，是吗?你要知道，在普兹克退休去为车队工作之前，他是安德麦最令人尊敬的工匠之一。$B$B他加入赛车队後的第一件事就是开发了双引擎赛车。如果他没有为技工协会工作过，这些事儿就不会那麽顺畅了，但谁会关心这个呢，对吧?再没有比赛车更让人关心的啦!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '噢，当然，我当然知道你在说什么。不过，恐怕我帮不上你的忙了。我的确是派了些人去搞一张燃料调节器的设计图来，可他们却都两手空空就回来了。$B$B' WHERE `entry` = 1181 AND `OfferRewardText_loc4` = '噢，当然，我当然知道你在说什麽。不过，恐怕我帮不上你的忙了。我的确是派了些人去搞一张燃料调节器的设计图来，可他们却都两手空空就回来了。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '嗯，先让我把这些蓝图复制一份，然后你就可以直接把它们送到普兹克那里去了。别让他觉得我这个赞助商把他给忘记了。$B$B' WHERE `entry` = 1182 AND `OfferRewardText_loc4` = '嗯，先让我把这些蓝图复制一份，然後你就可以直接把它们送到普兹克那里去了。别让他觉得我这个赞助商把他给忘记了。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '感谢你的帮助，$C。酋长也会对你大加赞赏的。$B$B哦，当然，我会向他提及你的名字。他经常找我谈话，而且非常尊重我的意见。$B$B现在如果你不介意的话，我还有很多事要做。如果你又见到了科兰，并且他有了关于这些生物的最新消息，那么就赶快回来告诉我─我会认真考虑这些昆虫给我们带来的威胁，并且认真地对待它们。$B$B' WHERE `entry` = 1184 AND `OfferRewardText_loc4` = '感谢你的帮助，$C。酋长也会对你大加赞赏的。$B$B哦，当然，我会向他提及你的名字。他经常找我谈话，而且非常尊重我的意见。$B$B现在如果你不介意的话，我还有很多事要做。如果你又见到了科兰，并且他有了关於这些生物的最新消息，那麽就赶快回来告诉我─我会认真考虑这些昆虫给我们带来的威胁，并且认真地对待它们。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你就是给普兹克帮忙的那个$R，是吗?我曾经就像你一样，在这里到处奔走，解决天知道哪里来的机械师交给我的各种问题。$B$B现在么，看看我!我已经是整个哥布林车队里最非凡的驾驶员了!$B$B' WHERE `entry` = 1186 AND `OfferRewardText_loc4` = '你就是给普兹克帮忙的那个$R，是吗?我曾经就像你一样，在这里到处奔走，解决天知道哪里来的机械师交给我的各种问题。$B$B现在麽，看看我!我已经是整个哥布林车队里最非凡的驾驶员了!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '只有拉泽瑞克才会注意到这个，然后他就非要我给这个推进器装个安全锁不可。这个推进器完全是使用爆盐动力驱动的。我已经对它的结构进行了特别的修改，保证它能够输出更多的动力，但是除非把动力调到十一节，否则拉泽瑞克这个速度狂是绝不会满意的!$B$B' WHERE `entry` = 1188 AND `OfferRewardText_loc4` = '只有拉泽瑞克才会注意到这个，然後他就非要我给这个推进器装个安全锁不可。这个推进器完全是使用爆盐动力驱动的。我已经对它的结构进行了特别的修改，保证它能够输出更多的动力，但是除非把动力调到十一节，否则拉泽瑞克这个速度狂是绝不会满意的!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '现在才有点像样了!我真希望看看那帮地精瞧见我装上这东西之后的表情。$B$B唉，我又要忙着创造新的世界纪录了!$B$B' WHERE `entry` = 1189 AND `OfferRewardText_loc4` = '现在才有点像样了!我真希望看看那帮地精瞧见我装上这东西之後的表情。$B$B唉，我又要忙着创造新的世界纪录了!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你将瑟银零件嵌入陷阱上的相应位置，并将冰霜之油灌了进去。当最后一滴油流入了陷阱的机关之后，陷阱恢复了正常状态。$B$B现在就等着某个心不在焉的巨魔上钩啦!$B$B' WHERE `entry` = 1193 AND `OfferRewardText_loc4` = '你将瑟银零件嵌入陷阱上的相应位置，并将冰霜之油灌了进去。当最後一滴油流入了陷阱的机关之後，陷阱恢复了正常状态。$B$B现在就等着某个心不在焉的巨魔上钩啦!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '精铁?真有趣……如果它真如你所说有那么强的抗热性能的话，那就能解释地精赛车最近的出色表现了。$B$B你带给我的这个样品是绝对是无价的。我将用它来做些测试，但我需要更多的矿石来将其投入实际的应用。$B$B' WHERE `entry` = 1194 AND `OfferRewardText_loc4` = '精铁?真有趣……如果它真如你所说有那麽强的抗热性能的话，那就能解释地精赛车最近的出色表现了。$B$B你带给我的这个样品是绝对是无价的。我将用它来做些测试，但我需要更多的矿石来将其投入实际的应用。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '嗯，是的，这瓶水对于我们完成目标很有帮助。因为和林精和半人马有共同的祖先，因此月井的水一定能帮助我们解开环绕半人马遗迹的永恒火焰的保护。$B$B' WHERE `entry` = 1196 AND `OfferRewardText_loc4` = '嗯，是的，这瓶水对於我们完成目标很有帮助。因为和林精和半人马有共同的祖先，因此月井的水一定能帮助我们解开环绕半人马遗迹的永恒火焰的保护。$B$B';
