UPDATE `locales_quest` SET `OfferRewardText_loc4` = '仔细地查看过马车的残骸之后，你发现它明显曾受到魔法和武器的双重攻击。似乎那场战斗的实力对比相当悬殊，因此很快就结束了，地上既没有血迹，也没有发现任何尸体。$B$B看来袭击者动作敏捷，而且颇有效率。$B$B' WHERE `entry` = 1437 AND `OfferRewardText_loc4` = '仔细地查看过马车的残骸之後，你发现它明显曾受到魔法和武器的双重攻击。似乎那场战斗的实力对比相当悬殊，因此很快就结束了，地上既没有血迹，也没有发现任何屍体。$B$B看来袭击者动作敏捷，而且颇有效率。$B$B';
