UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这正是史蒂威尔想要的宝石，不过在我让你拿给他之前，必须先去除其中的腐败成分—纳迦为科尔宝石灌输了强大的魔法，不过那是邪恶的魔法。$B$B告诉史蒂威尔，科尔宝石中的魔法能量都是纯正圣洁的，无论他想用它完成什么仪式都没有问题。$B$B我希望你知道自己在做什么，$C，你手里拿的可不是个简单的东西。$B$B' WHERE `entry` = 1442 AND `OfferRewardText_loc4` = '这正是史蒂威尔想要的宝石，不过在我让你拿给他之前，必须先去除其中的腐败成分—纳迦为科尔宝石灌输了强大的魔法，不过那是邪恶的魔法。$B$B告诉史蒂威尔，科尔宝石中的魔法能量都是纯正圣洁的，无论他想用它完成什麽仪式都没有问题。$B$B我希望你知道自己在做什麽，$C，你手里拿的可不是个简单的东西。$B$B';
