UPDATE `locales_quest` SET `OfferRewardText_loc4` = '阿塔哈卡神庙已经沉没在泪水之池底了?而且被绿龙军团给围了起来?!$B$B真是个了不起的发现呀，$C，不过显然有什么地方不对劲……$B$B' WHERE `entry` = 1448 AND `OfferRewardText_loc4` = '阿塔哈卡神庙已经沉没在泪水之池底了?而且被绿龙军团给围了起来?!$B$B真是个了不起的发现呀，$C，不过显然有什麽地方不对劲……$B$B';
