UPDATE `locales_quest` SET `OfferRewardText_loc4` = '很好，很好，$N。不知道这些东西品质如何，但应该可以满足莱弗维奇的需要了，除非他要的是十分罕见的品种。嗯，当然，如果他想要特殊品种的话，应该会事先有所说明的。$B$B他的清单上的下一件物品是怎么说的?$B$B' WHERE `entry` = 1458 AND `OfferRewardText_loc4` = '很好，很好，$N。不知道这些东西品质如何，但应该可以满足莱弗维奇的需要了，除非他要的是十分罕见的品种。嗯，当然，如果他想要特殊品种的话，应该会事先有所说明的。$B$B他的清单上的下一件物品是怎麽说的?$B$B';
