UPDATE `locales_quest` SET `OfferRewardText_loc4` = '好极了……过去我从来没有办法接近这本书，它被小心翼翼地保存在图书馆里，只要我试图接近它，其他人就会怀疑我。$B$B很好，你做的不错，我现在可以确信你有能力操纵你的小鬼了，那么就让我教你如何召唤小鬼吧。$B$B' WHERE `entry` = 1598 AND `OfferRewardText_loc4` = '好极了……过去我从来没有办法接近这本书，它被小心翼翼地保存在图书馆里，只要我试图接近它，其他人就会怀疑我。$B$B很好，你做的不错，我现在可以确信你有能力操纵你的小鬼了，那麽就让我教你如何召唤小鬼吧。$B$B';
