UPDATE `locales_quest` SET `OfferRewardText_loc4` = '做得好，$N。奥拉格对于天谴军团来说很重要。你已经向黑暗女王证明了你具备一个战士应有的技巧和决心，因此你理应得到更多的教导。$B$B' WHERE `entry` = 1819 AND `OfferRewardText_loc4` = '做得好，$N。奥拉格对於天谴军团来说很重要。你已经向黑暗女王证明了你具备一个战士应有的技巧和决心，因此你理应得到更多的教导。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊!你找到它们了!现在，阿加曼德家族最后的荣耀和记忆已经从这片被诅咒的土地上彻底消失了!现在，这个家族已经永远被人遗忘了!$B$B' WHERE `entry` = 1821 AND `OfferRewardText_loc4` = '啊!你找到它们了!现在，阿加曼德家族最後的荣耀和记忆已经从这片被诅咒的土地上彻底消失了!现在，这个家族已经永远被人遗忘了!$B$B';
