UPDATE `locales_quest` SET `OfferRewardText_loc4` = '嗯，这些真是很不错的亚麻布，我可以做出一件漂亮的长袍来。在我把裂隙宝石点缀在袍子上以后，你就会看见一件非常适合法师的衣裳!$B$B' WHERE `entry` = 1921 AND `OfferRewardText_loc4` = '嗯，这些真是很不错的亚麻布，我可以做出一件漂亮的长袍来。在我把裂隙宝石点缀在袍子上以後，你就会看见一件非常适合法师的衣裳!$B$B';
