UPDATE `locales_quest` SET `OfferRewardText_loc4` = '太好了，你终于来了。我的任务可不是那么简单，但对于整个法师界来说是非常关键的。如果你能帮忙的话，我相信你一定不会后悔的。$B$B' WHERE `entry` = 1943 AND `OfferRewardText_loc4` = '太好了，你终於来了。我的任务可不是那麽简单，但对於整个法师界来说是非常关键的。如果你能帮忙的话，我相信你一定不会後悔的。$B$B';
