UPDATE `locales_quest` SET `OfferRewardText_loc4` = '按照石头守护者的指引，你完全了解到了土灵、矮人和石腭怪的起源和历史。一阵轻微的嗡嗡声从圆盘中传出。石头守护者说:$B$B「圆盘已经集成完毕。请再次触摸诺甘农圆盘，获取属于你的资料拷贝。」$B$B' WHERE `entry` = 2278 AND `OfferRewardText_loc4` = '按照石头守护者的指引，你完全了解到了土灵、矮人和石齶怪的起源和历史。一阵轻微的嗡嗡声从圆盘中传出。石头守护者说:$B$B「圆盘已经集成完毕。请再次触摸诺甘农圆盘，获取属於你的资料拷贝。」$B$B';
