UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我很高兴能给你这条项链，强大的$C。你对我的帮助是无价的，我为此对你表示万分的感谢。请把它戴上吧，这是属于你的荣耀，请在别人问及的时候告诉他们，是我制作了这条项链!$B$B另外，如果你证明这条项链根本没有受到诅咒，那就更棒了。$B$B' WHERE `entry` = 2361 AND `OfferRewardText_loc4` = '我很高兴能给你这条项链，强大的$C。你对我的帮助是无价的，我为此对你表示万分的感谢。请把它戴上吧，这是属於你的荣耀，请在别人问及的时候告诉他们，是我制作了这条项链!$B$B另外，如果你证明这条项链根本没有受到诅咒，那就更棒了。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这么说来，我们那强大的盟友派到我这里来的就是你?太令人失望了……$B$B' WHERE `entry` = 2378 AND `OfferRewardText_loc4` = '这麽说来，我们那强大的盟友派到我这里来的就是你?太令人失望了……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '索尔想要改变部落的传统，我们破碎之手氏族必须对此保持警觉，这一点很重要。从人数上来说，我们很难和索尔的势力相抗衡，所以我们必须精于隐秘行动和欺诈。$B$B' WHERE `entry` = 2380 AND `OfferRewardText_loc4` = '索尔想要改变部落的传统，我们破碎之手氏族必须对此保持警觉，这一点很重要。从人数上来说，我们很难和索尔的势力相抗衡，所以我们必须精於隐秘行动和欺诈。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '又来一个?那个疯狂的食人妖派来的前五个倒楣鬼都已经塞了鲨鱼的牙缝。我希望你的结局不会那么惨。$B$B' WHERE `entry` = 2382 AND `OfferRewardText_loc4` = '又来一个?那个疯狂的食人妖派来的前五个倒楣鬼都已经塞了鲨鱼的牙缝。我希望你的结局不会那麽惨。$B$B';
