UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你是谁?!别那样偷偷摸摸地走到我后面来!小声点!你到底在干啥?没看见我很忙吗，你这个蠢货?$B$B你说什么?我在干啥?我在等下一个黑暗之门被打开，你以为我在干啥?在卫兵发现我们两个一起藏在灌木丛中之前赶紧走开……我要维护我的声誉。$B$B' WHERE `entry` = 2745 AND `OfferRewardText_loc4` = '你是谁?!别那样偷偷摸摸地走到我後面来!小声点!你到底在干啥?没看见我很忙吗，你这个蠢货?$B$B你说什麽?我在干啥?我在等下一个黑暗之门被打开，你以为我在干啥?在卫兵发现我们两个一起藏在灌木丛中之前赶紧走开……我要维护我的声誉。$B$B';
