UPDATE `locales_quest` SET `OfferRewardText_loc4` = '$N，看来你不过是酋长手下又一个容易自足的家伙，太让人失望了。$B$B我多么希望能在战场上光荣地死去，可是现在我却得困在这里，听从索尔的命令去训练新手!仔细看好了，孩子!$B$B' WHERE `entry` = 2756 AND `OfferRewardText_loc4` = '$N，看来你不过是酋长手下又一个容易自足的家伙，太让人失望了。$B$B我多麽希望能在战场上光荣地死去，可是现在我却得困在这里，听从索尔的命令去训练新手!仔细看好了，孩子!$B$B';
