UPDATE `locales_quest` SET `OfferRewardText_loc4` = '超级清洁器5200型突然停止了运行，「叮」的一声响，机器的盖子打开了，里面放着一只扎着蝴蝶结的小靶子。似乎这机器在清除物体表面的污垢以后会把物体包装起来。即使机器没有清理过什么，至少这东西被装在了一个漂亮的盒子里。$B$B好吧，让我们来看看它有没有清洁你放进去的东西……$B$B' WHERE `entry` = 2952 AND `OfferRewardText_loc4` = '超级清洁器5200型突然停止了运行，「叮」的一声响，机器的盖子打开了，里面放着一只紮着蝴蝶结的小靶子。似乎这机器在清除物体表面的污垢以後会把物体包装起来。即使机器没有清理过什麽，至少这东西被装在了一个漂亮的盒子里。$B$B好吧，让我们来看看它有没有清洁你放进去的东西……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '超级清洁器5200型动了起来，它剧烈地晃动着。在机器里面，覆盖在物品表面的污垢正在被清洁工具研成粉末!$B$B超级清洁器5200型停止了运转，熟悉的「叮」的声音过后，机器的盖子猛地打开了，里面摆着一只精心包装过的，扎着蝴蝶结的小靶子。$B$B' WHERE `entry` = 2953 AND `OfferRewardText_loc4` = '超级清洁器5200型动了起来，它剧烈地晃动着。在机器里面，覆盖在物品表面的污垢正在被清洁工具研成粉末!$B$B超级清洁器5200型停止了运转，熟悉的「叮」的声音过後，机器的盖子猛地打开了，里面摆着一只精心包装过的，紮着蝴蝶结的小靶子。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '充满了力量和权威的声音从石头卫士的口中发出:$B$B「当你再次接触底座的时候，你的圆盘将回到你手中。你必须先得到奥丹姆圆盘，把它们与已有的圆盘组合起来，然后你才能进入奥丹姆城。」$B$B' WHERE `entry` = 2954 AND `OfferRewardText_loc4` = '充满了力量和权威的声音从石头卫士的口中发出:$B$B「当你再次接触底座的时候，你的圆盘将回到你手中。你必须先得到奥丹姆圆盘，把它们与已有的圆盘组合起来，然後你才能进入奥丹姆城。」$B$B';
