UPDATE `locales_quest` SET `OfferRewardText_loc4` = '辛达尔说得对，$N─你确实很出色。作为一个冒险者，你比我们更有经验，谢谢你。$B$B恐怖图腾氏族比大多数牛头人更具有攻击性……我怀疑其他牛头人也会对这些家伙感到厌恶。你可能已经注意到了，艾泽拉斯的许多种族都有那么一部分害群之马。$B$B但这个问题我们还是以后再讨论吧。$B$B' WHERE `entry` = 2970 AND `OfferRewardText_loc4` = '辛达尔说得对，$N─你确实很出色。作为一个冒险者，你比我们更有经验，谢谢你。$B$B恐怖图腾氏族比大多数牛头人更具有攻击性……我怀疑其他牛头人也会对这些家伙感到厌恶。你可能已经注意到了，艾泽拉斯的许多种族都有那麽一部分害群之马。$B$B但这个问题我们还是以後再讨论吧。$B$B';
