UPDATE `locales_quest` SET `OfferRewardText_loc4` = '调剂将为我们的武器提供必要的成分。接下来，我们还需进行最后一个步骤来完成武器的锻造。$B$B' WHERE `entry` = 3511 AND `OfferRewardText_loc4` = '调剂将为我们的武器提供必要的成分。接下来，我们还需进行最後一个步骤来完成武器的锻造。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '天啊，我正在想为什么今天还没看到埃沃隆呢。我一直警告他得当心那些蜘蛛……$B$B' WHERE `entry` = 3519 AND `OfferRewardText_loc4` = '天啊，我正在想为什麽今天还没看到埃沃隆呢。我一直警告他得当心那些蜘蛛……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '太棒了，我就觉得你应该是个英雄人物!我并不打算欺骗你，我们的工作有些麻烦$N。如果我们可以专注于手边的任务，我们应该可以名列前茅。$B$B现在，让我们加快脚步吧……$B$B' WHERE `entry` = 3523 AND `OfferRewardText_loc4` = '太棒了，我就觉得你应该是个英雄人物!我并不打算欺骗你，我们的工作有些麻烦$N。如果我们可以专注於手边的任务，我们应该可以名列前茅。$B$B现在，让我们加快脚步吧……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '很好，$N，你选择接受我的指导真是明智之举!随便什么蠢货都可以成为初级工程学的专家—那些哥布林跟他们那满是辐射的老窝就是最好的证据。要成为出色的哥布林工程学专家，你必须有坚强的意志和稳固的双手—(我得强调稳固二字)。$B$B竖起你的耳朵，$N，你会学到许多东西的。$B$B' WHERE `entry` = 3526 AND `OfferRewardText_loc4` = '很好，$N，你选择接受我的指导真是明智之举!随便什麽蠢货都可以成为初级工程学的专家—那些哥布林跟他们那满是辐射的老窝就是最好的证据。要成为出色的哥布林工程学专家，你必须有坚强的意志和稳固的双手—(我得强调稳固二字)。$B$B竖起你的耳朵，$N，你会学到许多东西的。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我收集到哈卡的精华了!现在这卵充满着生命!难道哈卡的神话是真的?$B$B这不能让它成真，要是哈卡获得重生，不知道他会做出什么事来呢。我将确保这颗卵的安全，不让它落入坏人之手。$B$B我给你的任务都完成了，$N。你经历了一场传奇，你的作为也许会改变我们的世界。$B$B' WHERE `entry` = 3528 AND `OfferRewardText_loc4` = '我收集到哈卡的精华了!现在这卵充满着生命!难道哈卡的神话是真的?$B$B这不能让它成真，要是哈卡获得重生，不知道他会做出什麽事来呢。我将确保这颗卵的安全，不让它落入坏人之手。$B$B我给你的任务都完成了，$N。你经历了一场传奇，你的作为也许会改变我们的世界。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，杰迪加从艾萨拉送来了她的包裹。好极了，我正等着呢。$B$B杰迪加是个很好的女人……但也很危险。还有什么比这更好的?$B$B看看这个……石板保存的十分完好。你真是个好信差，$N。$B$B' WHERE `entry` = 3541 AND `OfferRewardText_loc4` = '啊，杰迪加从艾萨拉送来了她的包裹。好极了，我正等着呢。$B$B杰迪加是个很好的女人……但也很危险。还有什麽比这更好的?$B$B看看这个……石板保存的十分完好。你真是个好信差，$N。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些钱给你……去给你自已……<嗝>……买些新武器或什么的……$B$B去吧……<嗝>$B$B' WHERE `entry` = 3542 AND `OfferRewardText_loc4` = '这些钱给你……去给你自已……<嗝>……买些新武器或什麽的……$B$B去吧……<嗝>$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，塞尔哈石板……我是多么渴望能研究它呀。$B$B谢谢你，$N。告诉杰迪加，她做得很好。这东西的价值绝对符合她所要求的报酬啊!$B$B' WHERE `entry` = 3561 AND `OfferRewardText_loc4` = '啊，塞尔哈石板……我是多麽渴望能研究它呀。$B$B谢谢你，$N。告诉杰迪加，她做得很好。这东西的价值绝对符合她所要求的报酬啊!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '从他的字条看来他是欣喜若狂啊……高兴得有点过了头。$B$B也许有一天我要让他知道我是多么感谢他。哦，至少我们有理由在艾萨拉多停留一段时间了。$B$B这是你应得的那份酬劳。$B$B' WHERE `entry` = 3563 AND `OfferRewardText_loc4` = '从他的字条看来他是欣喜若狂啊……高兴得有点过了头。$B$B也许有一天我要让他知道我是多麽感谢他。哦，至少我们有理由在艾萨拉多停留一段时间了。$B$B这是你应得的那份酬劳。$B$B';
