UPDATE `locales_quest` SET `OfferRewardText_loc4` = '药剂师科雷对我非常友善……尽管这令我有些不安。如果他说这东西能帮我，那么我别无选择,我没有时间去寻找其他的解决方法了。我已经和牧师及萨满都谈过了，他们都无能为力。$B$B愿大地之母守护我的灵魂。$B$B' WHERE `entry` = 3569 AND `OfferRewardText_loc4` = '药剂师科雷对我非常友善……尽管这令我有些不安。如果他说这东西能帮我，那麽我别无选择,我没有时间去寻找其他的解决方法了。我已经和牧师及萨满都谈过了，他们都无能为力。$B$B愿大地之母守护我的灵魂。$B$B';
