UPDATE `locales_quest` SET `OfferRewardText_loc4` = '疲惫的旅者，感谢你来到此地!请允许我自我介绍─我是奎恩提斯，一名德鲁伊，同时也是玛法里恩和塞纳里奥议会的身份低微的仆人。我和我的同伴(珊蒂斯·羽月将军和护国者─或许你听说过我们)想与你谈谈你为达纳苏斯的范达尔·鹿盔所做的事情。$B$B在进一步交谈之前，我想声明我们的谈话仅限于你我之间。如果你对此无异议的话，我们就可以开始了。$B$B' WHERE `entry` = 3787 AND `OfferRewardText_loc4` = '疲惫的旅者，感谢你来到此地!请允许我自我介绍─我是奎恩提斯，一名德鲁伊，同时也是玛法里恩和塞纳里奥议会的身份低微的仆人。我和我的同伴(珊蒂斯·羽月将军和护国者─或许你听说过我们)想与你谈谈你为达纳苏斯的范达尔·鹿盔所做的事情。$B$B在进一步交谈之前，我想声明我们的谈话仅限於你我之间。如果你对此无异议的话，我们就可以开始了。$B$B';
