UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你成功了!我马上就研习这本说明书的内容，然后找出修复主动式负载平衡器的方法!我和棘齿城的斯布特瓦夫谈过了─他感谢你的帮助，并想要对你进行奖励。$B$B我也想感谢你，如果我能修好它的话，我会通知你的……$B$B' WHERE `entry` = 3924 AND `OfferRewardText_loc4` = '你成功了!我马上就研习这本说明书的内容，然後找出修复主动式负载平衡器的方法!我和棘齿城的斯布特瓦夫谈过了─他感谢你的帮助，并想要对你进行奖励。$B$B我也想感谢你，如果我能修好它的话，我会通知你的……$B$B';
