UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你找到了一只搁浅的小船。透过有些浑浊的水，你看到左船舷有很多洞，整只船被破坏得几乎只剩下龙骨了，似乎是有什么力量想要把这只船撕为两半。在右舷上有一个小小的羽月要塞标志。$B$B在船底下的泥土里，似乎有什么金属物品在闪光……$B$B' WHERE `entry` = 4125 AND `OfferRewardText_loc4` = '你找到了一只搁浅的小船。透过有些浑浊的水，你看到左船舷有很多洞，整只船被破坏得几乎只剩下龙骨了，似乎是有什麽力量想要把这只船撕为两半。在右舷上有一个小小的羽月要塞标志。$B$B在船底下的泥土里，似乎有什麽金属物品在闪光……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你说的很多，我确实疯了!我被人抢劫了!那些强盗抢了我祖传的配方!他们怎么敢这样做!在此之前我还不怎么恨那些黑铁矮人了!现在，哦……他们就是罪魁祸首!$B$B' WHERE `entry` = 4128 AND `OfferRewardText_loc4` = '你说的很多，我确实疯了!我被人抢劫了!那些强盗抢了我祖传的配方!他们怎麽敢这样做!在此之前我还不怎麽恨那些黑铁矮人了!现在，哦……他们就是罪魁祸首!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '谢谢你，$N。$B$B虽说心灵占卜术并不是多么精深的技艺，但我在过去的岁月中一直使用它来发现别人忽略的细节。我想，把它用到这把刀子上会让我们对拉斯卡尔的下落有更多的头绪。$B$B请稍等一会儿，虽然心灵占卜花不了多久，但是这种事情颇为费神。$B$B' WHERE `entry` = 4129 AND `OfferRewardText_loc4` = '谢谢你，$N。$B$B虽说心灵占卜术并不是多麽精深的技艺，但我在过去的岁月中一直使用它来发现别人忽略的细节。我想，把它用到这把刀子上会让我们对拉斯卡尔的下落有更多的头绪。$B$B请稍等一会儿，虽然心灵占卜花不了多久，但是这种事情颇为费神。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '感谢你把奎恩提斯看到的东西告诉我，$N。我下一次和他打牌的时候看来要小心一些了。$B$B拉斯卡尔应该可以应付那些豺狼人，他的实力还不至于弱到被豺狼人打得落花流水。也许在获得这些新的情报之后，你可以帮我们再去找找新的线索。$B$B' WHERE `entry` = 4130 AND `OfferRewardText_loc4` = '感谢你把奎恩提斯看到的东西告诉我，$N。我下一次和他打牌的时候看来要小心一些了。$B$B拉斯卡尔应该可以应付那些豺狼人，他的实力还不至於弱到被豺狼人打得落花流水。也许在获得这些新的情报之後，你可以帮我们再去找找新的线索。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '正义终于得到了伸张!你是个不平凡的$R，$N。戴上这枚勋章，这是你为部落和K.E.F.所做出的卓越贡献的象征。$B$B' WHERE `entry` = 4132 AND `OfferRewardText_loc4` = '正义终於得到了伸张!你是个不平凡的$R，$N。戴上这枚勳章，这是你为部落和K.E.F.所做出的卓越贡献的象徵。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你找到了一个很大的脓包状物体。看起来这东西粘糊糊的，有些地方还有硬质的瘤。这个脓包的高度和宽度足够装下一个人型生物……通过里面隐约可见的人形轮廓，你大概猜出了里面裹着的究竟是什么。$B$B' WHERE `entry` = 4135 AND `OfferRewardText_loc4` = '你找到了一个很大的脓包状物体。看起来这东西粘糊糊的，有些地方还有硬质的瘤。这个脓包的高度和宽度足够装下一个人型生物……通过里面隐约可见的人形轮廓，你大概猜出了里面裹着的究竟是什麽。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊!你找到他了!看来……我的小兄弟不愿来见我。太可惜了。我真希望能当面告诉他我们准备把他交给里维加兹，然后看看他脸上的表情。$B$B谢谢你，$N。你让我的家族感到很高兴。雷布里从来没有像现在这样平静过。$B$B' WHERE `entry` = 4136 AND `OfferRewardText_loc4` = '啊!你找到他了!看来……我的小兄弟不愿来见我。太可惜了。我真希望能当面告诉他我们准备把他交给里维加兹，然後看看他脸上的表情。$B$B谢谢你，$N。你让我的家族感到很高兴。雷布里从来没有像现在这样平静过。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我希望它们没有给你带来太多的麻烦，$N。我试图绕过它们─它们真是太疯狂了!$B$B我想要从它们身上跳过去……然后我就遭到了攻击!被植物攻击!$B$B' WHERE `entry` = 4141 AND `OfferRewardText_loc4` = '我希望它们没有给你带来太多的麻烦，$N。我试图绕过它们─它们真是太疯狂了!$B$B我想要从它们身上跳过去……然後我就遭到了攻击!被植物攻击!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '血瓣花?嗯……好吧，你最好向我解释整个计画，然后我才能够告诉你我是否能够帮助你。$B$B' WHERE `entry` = 4142 AND `OfferRewardText_loc4` = '血瓣花?嗯……好吧，你最好向我解释整个计画，然後我才能够告诉你我是否能够帮助你。$B$B';
