UPDATE `locales_quest` SET `OfferRewardText_loc4` = '玛尔冯很久之前就离开这里了，$N。他去塔纳利斯研究那里的古代食人妖遗迹去了。$B$B那么你刚才说你需要什么来着?$B$B' WHERE `entry` = 4147 AND `OfferRewardText_loc4` = '玛尔冯很久之前就离开这里了，$N。他去塔纳利斯研究那里的古代食人妖遗迹去了。$B$B那麽你刚才说你需要什麽来着?$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '很好，$N，你选择接受我的指导真是明智之举!随便什么蠢货都可以成为初级工程学的专家—那些哥布林跟他们那满是辐射的老窝就是最好的证据。要成为出色的哥布林工程学专家，你必须有坚强的意志和稳固的双手—(我得强调稳固二字)。$B$B竖起你的耳朵，$N，你会学到许多东西的。$B$B' WHERE `entry` = 4181 AND `OfferRewardText_loc4` = '很好，$N，你选择接受我的指导真是明智之举!随便什麽蠢货都可以成为初级工程学的专家—那些哥布林跟他们那满是辐射的老窝就是最好的证据。要成为出色的哥布林工程学专家，你必须有坚强的意志和稳固的双手—(我得强调稳固二字)。$B$B竖起你的耳朵，$N，你会学到许多东西的。$B$B';
