UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，你成功了!现在我可以配制药水并把它用到罗克诺特身上去了。他终于要成为我的爱情魔咒的牺牲品了!$B$B谢谢你，$N。你真是个爱情的斗士!$B$B' WHERE `entry` = 4201 AND `OfferRewardText_loc4` = '啊，你成功了!现在我可以配制药水并把它用到罗克诺特身上去了。他终於要成为我的爱情魔咒的牺牲品了!$B$B谢谢你，$N。你真是个爱情的斗士!$B$B';
