UPDATE `locales_quest` SET `OfferRewardText_loc4` = '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边的广袤土地上，到处都潜伏着天谴军团的势力。面对部落的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。$B$B' WHERE `entry` = 5094 AND `OfferRewardText_loc4` = '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边的广袤土地上，到处都潜伏着天谴军团的势力。面对部落的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那麽，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。$B$B';
