UPDATE `locales_quest` SET `OfferRewardText_loc4` = '哈哈!以后他们再想取笑我的主意时，就得先考虑一下了!$B$B感谢你的帮助，$N。如果没有你的帮助，我可找不到那么多乐子!$B$B' WHERE `entry` = 5163 AND `OfferRewardText_loc4` = '哈哈!以後他们再想取笑我的主意时，就得先考虑一下了!$B$B感谢你的帮助，$N。如果没有你的帮助，我可找不到那麽多乐子!$B$B';
