UPDATE `locales_quest` SET `OfferRewardText_loc4` = '护锅领主的钥匙打开了这口锅的控制板，然后就消失了─与前两口瘟疫之锅的钥匙一样。一种带着腐烂气息的物质在锅里剧烈地翻滚着。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为亡灵壁垒的暗影牧师范蒂丝带回一份样品。$B$B' WHERE `entry` = 5222 AND `OfferRewardText_loc4` = '护锅领主的钥匙打开了这口锅的控制板，然後就消失了─与前两口瘟疫之锅的钥匙一样。一种带着腐烂气息的物质在锅里剧烈地翻滚着。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为亡灵壁垒的暗影牧师范蒂丝带回一份样品。$B$B';
