UPDATE `locales_quest` SET `OfferRewardText_loc4` = '恭喜你，$N，你已经为我们打开了最后一口瘟疫之锅!迪瑟斯将很快找到中和这口锅中的毒素所需的试剂。$B$B至于你，我敢肯定高级执行官德灵顿会亲自向你表示感谢。没有你，我们反抗天谴军团的斗争决不会有这么大的进展。谢谢你，英雄!$B$B' WHERE `entry` = 5236 AND `OfferRewardText_loc4` = '恭喜你，$N，你已经为我们打开了最後一口瘟疫之锅!迪瑟斯将很快找到中和这口锅中的毒素所需的试剂。$B$B至於你，我敢肯定高级执行官德灵顿会亲自向你表示感谢。没有你，我们反抗天谴军团的斗争决不会有这麽大的进展。谢谢你，英雄!$B$B';
