UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊……你终于来找泰金了。很好。$B$B你应该已经知道我们已经不同于加入部落的那个时候了，我们变得更加强大。我们之所以强大，是因为我们能够适应变化─部落教会了我们许多东西。我们不再先击败我们的敌人再获取他们的力量，现在我们先获得力量，然后击败我们的敌人。$B$B虽然这其中的差别很小，但是你会明白的。我们的部族需要你去了解这些。$B$B' WHERE `entry` = 5649 AND `OfferRewardText_loc4` = '啊……你终於来找泰金了。很好。$B$B你应该已经知道我们已经不同於加入部落的那个时候了，我们变得更加强大。我们之所以强大，是因为我们能够适应变化─部落教会了我们许多东西。我们不再先击败我们的敌人再获取他们的力量，现在我们先获得力量，然後击败我们的敌人。$B$B虽然这其中的差别很小，但是你会明白的。我们的部族需要你去了解这些。$B$B';
