UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我听说了有援军要来的消息，你就是来帮助我们的那个$R吗?你是来帮助血色十字军征讨亡灵的吗?$B$B如果是这样，那么请靠近些听我说……$B$B' WHERE `entry` = 6141 AND `OfferRewardText_loc4` = '我听说了有援军要来的消息，你就是来帮助我们的那个$R吗?你是来帮助血色十字军征讨亡灵的吗?$B$B如果是这样，那麽请靠近些听我说……$B$B';
