UPDATE `locales_quest` SET `OfferRewardText_loc4` = '拉戈尔。弗雷多。特伊恩。都……死了……$B$B<弗林特紧紧抓住闭记。>$B$B他们在哪里?你有没有发现关于这个混蛋的更多消息，就是凋零者?$B$B' WHERE `entry` = 6185 AND `OfferRewardText_loc4` = '拉戈尔。弗雷多。特伊恩。都……死了……$B$B<弗林特紧紧抓住闭记。>$B$B他们在哪里?你有没有发现关於这个混蛋的更多消息，就是凋零者?$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '不。这……不!怎么可能?被遗忘者的探员?女妖之王的勇士?$B$B<大领主伯瓦尔·弗塔根沮丧万分。>$B$B' WHERE `entry` = 6186 AND `OfferRewardText_loc4` = '不。这……不!怎麽可能?被遗忘者的探员?女妖之王的勇士?$B$B<大领主伯瓦尔·弗塔根沮丧万分。>$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我的愤怒正在逐渐消退。我该怎么办呢?当我知道邪恶的力量靠近我的家园时，我的思绪就无法稳定下来，虽然它们现在很沉寂。也许这是件好事……也许我现在可以专注于一些好的事情，就像所有牛头人都应该做的那样。$B$B请收下这个作为你的奖励。$B$B' WHERE `entry` = 6283 AND `OfferRewardText_loc4` = '我的愤怒正在逐渐消退。我该怎麽办呢?当我知道邪恶的力量靠近我的家园时，我的思绪就无法稳定下来，虽然它们现在很沉寂。也许这是件好事……也许我现在可以专注於一些好的事情，就像所有牛头人都应该做的那样。$B$B请收下这个作为你的奖励。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，$N，你拿到盖亚之种了。看看这些种子将如何给土地带来新的活力吧，只有这些纯净的植物可以治愈大地的创伤。$B$B<塔姆拉开始吟唱魔法。>$B$B' WHERE `entry` = 6301 AND `OfferRewardText_loc4` = '啊，$N，你拿到盖亚之种了。看看这些种子将如何给土地带来新的活力吧，只有这些纯净的植物可以治癒大地的创伤。$B$B<塔姆拉开始吟唱魔法。>$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，一份供给订单。毫无疑问，你想要带着这份订单去幽暗城。那么就快点动身吧，瑟伯切尔急需物资补给。$B$B' WHERE `entry` = 6321 AND `OfferRewardText_loc4` = '啊，一份供给订单。毫无疑问，你想要带着这份订单去幽暗城。那麽就快点动身吧，瑟伯切尔急需物资补给。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '奈莎送来的包裹?谢谢你，$N!她说过如果她在鲁瑟兰村钓到鱼的话，就会托人把样品送到我这里来。她认为那里的鱼可能和这边的不太一样……$B$B我的天啊!这条鱼的个头几乎比这里的同类大了两倍!这些鳞片都有拳头那么大!太令人惊奇了!$B$B' WHERE `entry` = 6342 AND `OfferRewardText_loc4` = '奈莎送来的包裹?谢谢你，$N!她说过如果她在鲁瑟兰村钓到鱼的话，就会托人把样品送到我这里来。她认为那里的鱼可能和这边的不太一样……$B$B我的天啊!这条鱼的个头几乎比这里的同类大了两倍!这些鳞片都有拳头那麽大!太令人惊奇了!$B$B';
