UPDATE `locales_quest` SET `OfferRewardText_loc4` = '哈!我就知道她会喜欢的!除了一大块鲜美多汁的烤肉，没有什么能让这样一位小姐的脸颊泛起红光了!$B$B谢谢你，$N。你帮了我的大忙。这是我给你的一点报酬，要是我邀请你参加我的婚礼，可别感到惊讶啊!$B$B' WHERE `entry` = 6386 AND `OfferRewardText_loc4` = '哈!我就知道她会喜欢的!除了一大块鲜美多汁的烤肉，没有什麽能让这样一位小姐的脸颊泛起红光了!$B$B谢谢你，$N。你帮了我的大忙。这是我给你的一点报酬，要是我邀请你参加我的婚礼，可别感到惊讶啊!$B$B';
