UPDATE `locales_quest` SET `OfferRewardText_loc4` = '很好!这真是个好消息，也许今天晚上我们就不会有那么多不请自来的访客了。$B$B就向我说过的一样，我欠你的人情……这些东西里面有没有你用得到的?$B$B' WHERE `entry` = 6461 AND `OfferRewardText_loc4` = '很好!这真是个好消息，也许今天晚上我们就不会有那麽多不请自来的访客了。$B$B就向我说过的一样，我欠你的人情……这些东西里面有没有你用得到的?$B$B';
