UPDATE `locales_quest` SET `OfferRewardText_loc4` = '笼罩着冬幕的传奇与故事在这几年中已经慢慢地由广为人知变得较为隐密了。我知道哥布林们为了他们自己而正在帮忙提倡这个节庆，而我们族人的反应至少在某种形式上对于保住这些传说是有帮助的。$B$B你想要越过物质并且学习我们的过去是值得敬佩的特质，年轻的$C。我向你的智慧致敬。$B$B' WHERE `entry` = 7061 AND `OfferRewardText_loc4` = '笼罩着冬幕的传奇与故事在这几年中已经慢慢地由广为人知变得较为隐密了。我知道哥布林们为了他们自己而正在帮忙提倡这个节庆，而我们族人的反应至少在某种形式上对於保住这些传说是有帮助的。$B$B你想要越过物质并且学习我们的过去是值得敬佩的特质，年轻的$C。我向你的智慧致敬。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这个消息真是再好不过了，$N!谢谢你!$B$B虽然你无法带回札尔塔的遗体来让我当面质问这个塞纳留斯的长子，但是半人马的意志会慢慢被消磨，他们对于鲜血的渴望会慢慢衰减─我们希望如此。$B$B我这里有些东西，是为那些帮助我们的冒险者准备的。你帮了我们的大忙，因此，你可以从中选择一件来作为报酬。$B$B' WHERE `entry` = 7065 AND `OfferRewardText_loc4` = '这个消息真是再好不过了，$N!谢谢你!$B$B虽然你无法带回札尔塔的遗体来让我当面质问这个塞纳留斯的长子，但是半人马的意志会慢慢被消磨，他们对於鲜血的渴望会慢慢衰减─我们希望如此。$B$B我这里有些东西，是为那些帮助我们的冒险者准备的。你帮了我们的大忙，因此，你可以从中选择一件来作为报酬。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '那么说来我的兄弟终于安息了?我很荣幸能够在有生之年得知这件事。他的傲慢自大和愤怒让我以为他已经远离了我们，但是他……他的牺牲证明我错了─他已经重生了。他尽到了自己对大自然的职责。$B$B谢谢你，$N。你让我看到了一丝我原以为早已丧失的希望。这颗种子对于这个饱受战火创伤的世界来说非常重要……我已经感觉到了这一点。$B$B' WHERE `entry` = 7066 AND `OfferRewardText_loc4` = '那麽说来我的兄弟终於安息了?我很荣幸能够在有生之年得知这件事。他的傲慢自大和愤怒让我以为他已经远离了我们，但是他……他的牺牲证明我错了─他已经重生了。他尽到了自己对大自然的职责。$B$B谢谢你，$N。你让我看到了一丝我原以为早已丧失的希望。这颗种子对於这个饱受战火创伤的世界来说非常重要……我已经感觉到了这一点。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，这些对我的魔法来说简直是太完美了。给你，你可以拿走这些饰物中的一样，然后就赶快离开吧……我要开始进行研究工作了。$B$B' WHERE `entry` = 7068 AND `OfferRewardText_loc4` = '啊，这些对我的魔法来说简直是太完美了。给你，你可以拿走这些饰物中的一样，然後就赶快离开吧……我要开始进行研究工作了。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些真是太完美了，$N。我还征集了一些其他的冒险中从那里帮我收集水晶，所以我有充足的材料做出这些东西……嗯，从中拿一件作为你辛勤工作的奖励吧。感谢你把这些样品交给我来进行研究。$B$B' WHERE `entry` = 7070 AND `OfferRewardText_loc4` = '这些真是太完美了，$N。我还徵集了一些其他的冒险中从那里帮我收集水晶，所以我有充足的材料做出这些东西……嗯，从中拿一件作为你辛勤工作的奖励吧。感谢你把这些样品交给我来进行研究。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得好!墓地对于我们控制奥特兰克山谷具有十分重要的价值。当你占领一座墓地之后，联盟在这里的优势就得到了进一步的巩固。$B$B现在回到战场上去，$N。如果你再看到被部落占领的墓地……你就知道该怎么做了!$B$B' WHERE `entry` = 7081 AND `OfferRewardText_loc4` = '干得好!墓地对於我们控制奥特兰克山谷具有十分重要的价值。当你占领一座墓地之後，联盟在这里的优势就得到了进一步的巩固。$B$B现在回到战场上去，$N。如果你再看到被部落占领的墓地……你就知道该怎麽做了!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得好，$N!当我们控制了墓地之后，敌人的鲜血就将染红奥特兰克山谷的雪地!$B$B' WHERE `entry` = 7082 AND `OfferRewardText_loc4` = '干得好，$N!当我们控制了墓地之後，敌人的鲜血就将染红奥特兰克山谷的雪地!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你成功了!干得好，$N!$B$B只要我们控制了矿坑，并派遣部队驻扎在那里，我们就可以源源不断地获得物资补给了。$B$B' WHERE `entry` = 7122 AND `OfferRewardText_loc4` = '你成功了!干得好，$N!$B$B只要我们控制了矿坑，并派遣部队驻紮在那里，我们就可以源源不断地获得物资补给了。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你找到它们了!干得好，$N!这些计画可以告诉我们，那些雷矛部族的家伙究竟想要从这次愚蠢的入侵中获得什么好处。$B$B哈哈!迄今为止，他们所得到的只是他们将军的葬礼!$B$B' WHERE `entry` = 7142 AND `OfferRewardText_loc4` = '你找到它们了!干得好，$N!这些计画可以告诉我们，那些雷矛部族的家伙究竟想要从这次愚蠢的入侵中获得什麽好处。$B$B哈哈!迄今为止，他们所得到的只是他们将军的葬礼!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你所感觉到的激情是你的灵魂正在被唤醒的证明─它已经响应了战争的召唤。$B$B现在你是霜狼氏族的一员了，$N。恭喜你。$B$B一直戴着这枚徽记吧。当你在霜狼中的军阶再次提升后就回来找我，我会给你颁发更高级、更强大的徽记。$B$B也许有一天你在霜狼氏族中获得最尊贵的荣誉。当那一天到来的时候，你将获得整个氏族军队的控制权。$B$B' WHERE `entry` = 7161 AND `OfferRewardText_loc4` = '你所感觉到的激情是你的灵魂正在被唤醒的证明─它已经响应了战争的召唤。$B$B现在你是霜狼氏族的一员了，$N。恭喜你。$B$B一直戴着这枚徽记吧。当你在霜狼中的军阶再次提升後就回来找我，我会给你颁发更高级、更强大的徽记。$B$B也许有一天你在霜狼氏族中获得最尊贵的荣誉。当那一天到来的时候，你将获得整个氏族军队的控制权。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '拿着这枚徽记，$N。当你在雷矛部族中的军阶再次提升后就回来找我，我会给你颁发更高级、更强大的徽记。$B$B也许有一天你会成为新的英雄，到那个时候，你就可以获得对整个部族军队的控制权了。$B$B' WHERE `entry` = 7162 AND `OfferRewardText_loc4` = '拿着这枚徽记，$N。当你在雷矛部族中的军阶再次提升後就回来找我，我会给你颁发更高级、更强大的徽记。$B$B也许有一天你会成为新的英雄，到那个时候，你就可以获得对整个部族军队的控制权了。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '国王也已经听闻了你的英雄事迹，$C。继续为雷矛部族作战吧!$B$B' WHERE `entry` = 7169 AND `OfferRewardText_loc4` = '国王也已经听闻了你的英雄事蹟，$C。继续为雷矛部族作战吧!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些材料正好可以用。我会将它们溶解然后再把它们重新铸造起来，然后看起来绝对不会看出来是从雷矛那些懦夫那里来的!$B$B谢谢你，$N。让我为你清洁一下你的护甲……$B$B' WHERE `entry` = 7224 AND `OfferRewardText_loc4` = '这些材料正好可以用。我会将它们溶解然後再把它们重新铸造起来，然後看起来绝对不会看出来是从雷矛那些懦夫那里来的!$B$B谢谢你，$N。让我为你清洁一下你的护甲……$B$B';
