UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你拿到网了!干得好，$N!蕾瑟塔蒂丝和她的同类一样，不顾一切地滥用魔法，对我们的世界造成了巨大的威胁。他们认为自己是魔法的主人，却完全没有意识到自己其实是魔法的努力。她的死让我感到遗憾，但是这是必须的。$N$N谢谢你，$N。我会找一块开阔的地方安全地释放掉网中的能量，并将其摧毁，以防止它再惹出什么乱子来。$B$B' WHERE `entry` = 7488 AND `OfferRewardText_loc4` = '你拿到网了!干得好，$N!蕾瑟塔蒂丝和她的同类一样，不顾一切地滥用魔法，对我们的世界造成了巨大的威胁。他们认为自己是魔法的主人，却完全没有意识到自己其实是魔法的努力。她的死让我感到遗憾，但是这是必须的。$N$N谢谢你，$N。我会找一块开阔的地方安全地释放掉网中的能量，并将其摧毁，以防止它再惹出什麽乱子来。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你干得很好，$N。这张网包含了大量厄运之槌中的能量，我认为如果它继续留在像蕾瑟塔蒂丝这样的家伙手里，会对我们造成很大的威胁。我对于她的死感到悲伤，但是谁让她多此一举地制造了这张网呢?$B$B谢谢你，$N。我会把网送到那些比蕾瑟塔蒂丝更有负责感的魔法学员那里，他们将负责保管它。$B$B' WHERE `entry` = 7489 AND `OfferRewardText_loc4` = '你干得很好，$N。这张网包含了大量厄运之槌中的能量，我认为如果它继续留在像蕾瑟塔蒂丝这样的家伙手里，会对我们造成很大的威胁。我对於她的死感到悲伤，但是谁让她多此一举地制造了这张网呢?$B$B谢谢你，$N。我会把网送到那些比蕾瑟塔蒂丝更有负责感的魔法学员那里，他们将负责保管它。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这对于部落来说是一次伟大的胜利，$N。你多次让你的酋长感到荣耀，现在是酋长赐予你荣耀的时候了。$B$B' WHERE `entry` = 7490 AND `OfferRewardText_loc4` = '这对於部落来说是一次伟大的胜利，$N。你多次让你的酋长感到荣耀，现在是酋长赐予你荣耀的时候了。$B$B';
