UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这么多年以来，我都被她那迷人的外表欺骗了。最终，正义得到了伸张，暴风城的荣耀终于恢复了!今天，我们要欢庆这个伟大的胜利!$B$B' WHERE `entry` = 7495 AND `OfferRewardText_loc4` = '这麽多年以来，我都被她那迷人的外表欺骗了。最终，正义得到了伸张，暴风城的荣耀终於恢复了!今天，我们要欢庆这个伟大的胜利!$B$B';
