UPDATE `locales_quest` SET `OfferRewardText_loc4` = '棒极了……每当我们从血神的爪牙那儿夺得一块宝石，离彻底消灭他们就更近了一步。你高尚的行为为赞达拉以及你本人赢得了无上的荣誉。$B$B记住，$N，你可以继续利用祭坛摧毁在祖尔格拉布找到的宝石。每摧毁一块，你将获得1枚荣誉勋章!要是你还没有获得荣誉勋章，记得在背包中多留些空位。$B$B' WHERE `entry` = 8240 AND `OfferRewardText_loc4` = '棒极了……每当我们从血神的爪牙那儿夺得一块宝石，离彻底消灭他们就更近了一步。你高尚的行为为赞达拉以及你本人赢得了无上的荣誉。$B$B记住，$N，你可以继续利用祭坛摧毁在祖尔格拉布找到的宝石。每摧毁一块，你将获得1枚荣誉勳章!要是你还没有获得荣誉勳章，记得在背包中多留些空位。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '难以置信。数年来，裂片吸收了绿龙的能量，变得更加强大。$B$B现在我对你没什么要求啦。有了这块裂片，我将再次拥有铸造秘法的能力。我铸造的第一件物品是给你的，$N，你得选择……$B$B' WHERE `entry` = 8253 AND `OfferRewardText_loc4` = '难以置信。数年来，裂片吸收了绿龙的能量，变得更加强大。$B$B现在我对你没什麽要求啦。有了这块裂片，我将再次拥有铸造秘法的能力。我铸造的第一件物品是给你的，$N，你得选择……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你赢得了我最诚挚的敬意。你对于塞纳里奥城堡的帮助显示了你真正的勇气。$B$B' WHERE `entry` = 8280 AND `OfferRewardText_loc4` = '你赢得了我最诚挚的敬意。你对於塞纳里奥城堡的帮助显示了你真正的勇气。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '就和我怀疑的一样。我可以解译出石板上的所有文字，但是这些文字之间没有任何逻辑关系或者含义。现在还不知道暮光之锤究竟用了什么样的密码来掩盖这些文字的含义……我们必须找到一些更加了解这方面资讯的人。$B$B' WHERE `entry` = 8284 AND `OfferRewardText_loc4` = '就和我怀疑的一样。我可以解译出石板上的所有文字，但是这些文字之间没有任何逻辑关系或者含义。现在还不知道暮光之锤究竟用了什麽样的密码来掩盖这些文字的含义……我们必须找到一些更加了解这方面资讯的人。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<指挥官玛尔利斯抱住他的胸前。>$B$B克苏恩?这到底是什么意思?什么是克苏恩?这个魔鬼怎么会把我可爱的娜塔莉雅变成你们所说的怪物?$B$B' WHERE `entry` = 8306 AND `OfferRewardText_loc4` = '<指挥官玛尔利斯抱住他的胸前。>$B$B克苏恩?这到底是什麽意思?什麽是克苏恩?这个魔鬼怎麽会把我可爱的娜塔莉雅变成你们所说的怪物?$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这本书里包含几种常见的食谱还有一些很特别的食谱。浏览了几秒钟之后，你发现一个跟沙虫有关的食谱。$B$B' WHERE `entry` = 8307 AND `OfferRewardText_loc4` = '这本书里包含几种常见的食谱还有一些很特别的食谱。浏览了几秒钟之後，你发现一个跟沙虫有关的食谱。$B$B';
