UPDATE `locales_quest` SET `OfferRewardText_loc4` = '太好了，我的宠物制作完成了!$B$B<伊普斯很快将玩偶填充好，紧紧抱住它。>$B$B啊，这些巫毒羽毛拥有多么神奇的力量啊……$B$B' WHERE `entry` = 8422 AND `OfferRewardText_loc4` = '太好了，我的宠物制作完成了!$B$B<伊普斯很快将玩偶填充好，紧紧抱住它。>$B$B啊，这些巫毒羽毛拥有多麽神奇的力量啊……$B$B';
