UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊…我从风中的话听到有非我部族的人想找木喉熊怪与他们结盟。我欢迎你，但你必须知道我的部族对陌生人是很冷淡的。$B$B这些是试炼时期，而我们只能信任选择与我们一起抵抗土地腐败的人…并向我们证明他们自己。不这么做的人就会在进入要塞时感受到明显的敌意。$B$B' WHERE `entry` = 8462 AND `OfferRewardText_loc4` = '啊…我从风中的话听到有非我部族的人想找木喉熊怪与他们结盟。我欢迎你，但你必须知道我的部族对陌生人是很冷淡的。$B$B这些是试炼时期，而我们只能信任选择与我们一起抵抗土地腐败的人…并向我们证明他们自己。不这麽做的人就会在进入要塞时感受到明显的敌意。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这个图腾…我知道它是死木部族的东西，但是它发出浓烈的腐败恶臭。让我们的手足与我们反目成仇的邪恶东西一定就在这个物体里。$B$B你把这个拿来给我们是很明智的行为，$N。或许透过研究和仪式，我们可以了解是什么污染了我们手足的心智。谢谢你，朋友 – 请收下这个以答谢你的发现。$B$B' WHERE `entry` = 8470 AND `OfferRewardText_loc4` = '这个图腾…我知道它是死木部族的东西，但是它发出浓烈的腐败恶臭。让我们的手足与我们反目成仇的邪恶东西一定就在这个物体里。$B$B你把这个拿来给我们是很明智的行为，$N。或许透过研究和仪式，我们可以了解是什麽污染了我们手足的心智。谢谢你，朋友 – 请收下这个以答谢你的发现。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '的确，这是最幸运的事了。如果这些生物能维持永远的和平，对我们在卡林多的事务很有助益…这项事务是夜精灵们无法自行解决的。我会立即通知其他联盟的领导者，并会发送进一步的公文!$B$B至于你，$N…你在外交手腕和行为上都表现了你的勇气。谢谢你，整个联盟也感谢你。$B$B' WHERE `entry` = 8484 AND `OfferRewardText_loc4` = '的确，这是最幸运的事了。如果这些生物能维持永远的和平，对我们在卡林多的事务很有助益…这项事务是夜精灵们无法自行解决的。我会立即通知其他联盟的领导者，并会发送进一步的公文!$B$B至於你，$N…你在外交手腕和行为上都表现了你的勇气。谢谢你，整个联盟也感谢你。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '的确，这是个偶然又幸运的转机。盼和平永随这些生物，这一定会让我们在保卫卡林多上占优势，以免于外在威胁。我会立刻通知部落其他首领，并派遣外交使节!$B$B至于你，$N…你已在外交及行动上展现了勇气。我和全部落都感谢你。$B$B' WHERE `entry` = 8485 AND `OfferRewardText_loc4` = '的确，这是个偶然又幸运的转机。盼和平永随这些生物，这一定会让我们在保卫卡林多上占优势，以免於外在威胁。我会立刻通知部落其他首领，并派遣外交使节!$B$B至於你，$N…你已在外交及行动上展现了勇气。我和全部落都感谢你。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '做的好，$N。少了他们的工蝎，异种蝎就很难修补他们虫巢结构所受的伤害。$B$B' WHERE `entry` = 8502 AND `OfferRewardText_loc4` = '做的好，$N。少了他们的工蠍，异种蠍就很难修补他们虫巢结构所受的伤害。$B$B';
