UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些铜锭很好，谢谢你没有打亮它们。要将它们熔解做成战争要用的东西时，不需要把它们弄得那么漂亮。我会把它们堆放好，也会确定你的名字有被记下。如果你有兴趣帮我另外带20个的话再来和我谈谈。$B$B' WHERE `entry` = 8532 AND `OfferRewardText_loc4` = '这些铜锭很好，谢谢你没有打亮它们。要将它们熔解做成战争要用的东西时，不需要把它们弄得那麽漂亮。我会把它们堆放好，也会确定你的名字有被记下。如果你有兴趣帮我另外带20个的话再来和我谈谈。$B$B';
