UPDATE `locales_quest` SET `OfferRewardText_loc4` = '先处理当务之急，$N!我们必须搞清楚艾索雷葛斯到底在石板上写了什么。$B$B你说他叫你做一个奥金浮标而这只是个概要图吗?可是他会用龙语写还真奇怪。那个讨厌的老家伙知道我看不懂这乱七八糟的文字。$B$B如果有用的话，我需要我的水晶球护目镜，一只500磅的鸡和〝龙语傻瓜教程〞第二卷。不需要按照顺序。$B$B' WHERE `entry` = 8576 AND `OfferRewardText_loc4` = '先处理当务之急，$N!我们必须搞清楚艾索雷葛斯到底在石板上写了什麽。$B$B你说他叫你做一个奥金浮标而这只是个概要图吗?可是他会用龙语写还真奇怪。那个讨厌的老家伙知道我看不懂这乱七八糟的文字。$B$B如果有用的话，我需要我的水晶球护目镜，一只500磅的鸡和〝龙语傻瓜教程〞第二卷。不需要按照顺序。$B$B';
