UPDATE `locales_quest` SET `OfferRewardText_loc4` = '瓦拉斯塔兹的灵魂终于平静了，勇士。所有的守护巨龙都在关注着你的进展。他们知道你的身边有强大的盟友。$B$B我奉命送给你一些东西，希望它可以在这场战斗中帮助你。好好使用它……$B$B' WHERE `entry` = 8730 AND `OfferRewardText_loc4` = '瓦拉斯塔兹的灵魂终於平静了，勇士。所有的守护巨龙都在关注着你的进展。他们知道你的身边有强大的盟友。$B$B我奉命送给你一些东西，希望它可以在这场战斗中帮助你。好好使用它……$B$B';
