UPDATE `locales_quest` SET `OfferRewardText_loc4` = '幽光沉默着，除了有时会发出一些低沉的哼声。真古怪，它可以借由思想与你沟通。$B$B' WHERE `entry` = 8733 AND `OfferRewardText_loc4` = '幽光沉默着，除了有时会发出一些低沉的哼声。真古怪，它可以藉由思想与你沟通。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '如果伊兰尼库斯拒绝的话，那么我们永远无法将他唤醒。然而，他的企图却让他进入我们的世界。他想要摧毁玛法里恩的肉身。如果成功的话，那么意味着翡翠梦境一个最强大的盟友的终结。如果玛法里恩倒下了，那么梦魇将会吞噬整个世界……$B$B' WHERE `entry` = 8734 AND `OfferRewardText_loc4` = '如果伊兰尼库斯拒绝的话，那麽我们永远无法将他唤醒。然而，他的企图却让他进入我们的世界。他想要摧毁玛法里恩的肉身。如果成功的话，那麽意味着翡翠梦境一个最强大的盟友的终结。如果玛法里恩倒下了，那麽梦魇将会吞噬整个世界……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你办到了!万岁!$B$B梅特森已经飞回去冬天爷爷的兽栏里了－－是的，梅特森是会飞的－－就在不久之前!这个尘土有点像是个符咒;我知道它可以的。你拯救了冬幕节还有熏木牧场免于疾病的侵袭。谢谢你，$N。$B$B听着……因为你对这里的贡献，我希望你可以拿着这个。这是一个非常特别的东西;如果你有坐骑的话，我想你可以好好的试试它。冬幕节快乐!$B$B' WHERE `entry` = 8746 AND `OfferRewardText_loc4` = '你办到了!万岁!$B$B梅特森已经飞回去冬天爷爷的兽栏里了－－是的，梅特森是会飞的－－就在不久之前!这个尘土有点像是个符咒;我知道它可以的。你拯救了冬幕节还有燻木牧场免於疾病的侵袭。谢谢你，$N。$B$B听着……因为你对这里的贡献，我希望你可以拿着这个。这是一个非常特别的东西;如果你有坐骑的话，我想你可以好好的试试它。冬幕节快乐!$B$B';
