UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你将角鹰兽的蛋放入机器，随后里面传来了一些奇怪的机械声响和嘟嘟声。$B$B似乎测蛋器正在为这颗蛋称重、测量和包装。真是快捷又完善的服务!$B$B' WHERE `entry` = 8893 AND `OfferRewardText_loc4` = '你将角鹰兽的蛋放入机器，随後里面传来了一些奇怪的机械声响和嘟嘟声。$B$B似乎测蛋器正在为这颗蛋称重、测量和包装。真是快捷又完善的服务!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这勾起了好久前的回忆，$N。艾妮亚·托尔。这本来应该是我的名字，你知道吗。我们本来会在湖岸边有一场美丽的婚礼。当他退休后，我们就会找个农场隐退。$B$B不过，那都是梦。$B$B如果他现在看到我，我怀疑他还会不会在我身上看到艾妮亚。只有冰冷的躯体和已死的心……$B$B' WHERE `entry` = 8902 AND `OfferRewardText_loc4` = '这勾起了好久前的回忆，$N。艾妮亚·托尔。这本来应该是我的名字，你知道吗。我们本来会在湖岸边有一场美丽的婚礼。当他退休後，我们就会找个农场隐退。$B$B不过，那都是梦。$B$B如果他现在看到我，我怀疑他还会不会在我身上看到艾妮亚。只有冰冷的躯体和已死的心……$B$B';
