UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你真的不需要提供这些!真的，你不需要。不知道那个梅兹在想些什么，不过真的没有人会穿着这些袍子进入纳克萨玛斯。$B$B<军需筹备官石汉叹了口气>又是一堆我要必须要送到前线的垃圾，钱柏一定又会来跟我抱怨的。$B$B' WHERE `entry` = 9194 AND `OfferRewardText_loc4` = '你真的不需要提供这些!真的，你不需要。不知道那个梅兹在想些什麽，不过真的没有人会穿着这些袍子进入纳克萨玛斯。$B$B<军需筹备官石汉叹了口气>又是一堆我要必须要送到前线的垃圾，钱柏一定又会来跟我抱怨的。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你在笑什么?有什么那么好笑?听着，$G小子:女孩;，千万不要小看侏儒作战小鸡，他们在战役中是多么的重要啊，因为侏儒作战小鸡是唯一能够在有瘟疫的环境中生存并消灭那些被传染的昆虫和瘟疫带原者，大家都知道机器人都是对疾病免疫的。$B$B我想你现在应该觉得自己没有想像中的聪明了吧，大笨蛋……$B$B' WHERE `entry` = 9197 AND `OfferRewardText_loc4` = '你在笑什麽?有什麽那麽好笑?听着，$G小子:女孩;，千万不要小看侏儒作战小鸡，他们在战役中是多麽的重要啊，因为侏儒作战小鸡是唯一能够在有瘟疫的环境中生存并消灭那些被传染的昆虫和瘟疫带原者，大家都知道机器人都是对疾病免疫的。$B$B我想你现在应该觉得自己没有想像中的聪明了吧，大笨蛋……$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<军需筹备官石汉拿了一瓶强效秘法防护药水起来，然后一口喝下>$B$B哇!这个还真好喝!好喝!$B$B' WHERE `entry` = 9201 AND `OfferRewardText_loc4` = '<军需筹备官石汉拿了一瓶强效秘法防护药水起来，然後一口喝下>$B$B哇!这个还真好喝!好喝!$B$B';
