UPDATE `locales_quest` SET `RequestItemsText_loc4` = '呀，也许我应该亲自去手刃那些该死的纳迦!显然，你是不会去做这个的。$B$B也许我该给你找些针线活，让你不至于太清闲。' WHERE `entry` = 664 AND `RequestItemsText_loc4` = '呀，也许我应该亲自去手刃那些该死的纳迦!显然，你是不会去做这个的。$B$B也许我该给你找些针线活，让你不至於太清闲。';
