UPDATE `locales_quest` SET `RequestItemsText_loc4` = '我们得到那瓶水之后就要尽快把它送给我在千针石林的朋友，劳恩。他需要这瓶水，也比我们更了解它的用处。' WHERE `entry` = 1195 AND `RequestItemsText_loc4` = '我们得到那瓶水之後就要尽快把它送给我在千针石林的朋友，劳恩。他需要这瓶水，也比我们更了解它的用处。';
