UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你好，$N。特沃什已经向我解释过了你的来意。在你寻找那名与外交使节的失踪有着直接联系的人的时候，我一直在关注着事态的发展，最后我们决定先找到你，以确保此事处理得妥善迅速。' WHERE `entry` = 1267 AND `RequestItemsText_loc4` = '你好，$N。特沃什已经向我解释过了你的来意。在你寻找那名与外交使节的失踪有着直接联系的人的时候，我一直在关注着事态的发展，最後我们决定先找到你，以确保此事处理得妥善迅速。';
