UPDATE `locales_quest` SET `RequestItemsText_loc4` = '只要我有了足够的样本，就可以开始真正的研究了。有了这些从黑暗深渊里找到的萨特和纳迦的脑干，我就能找出这两种被魔法扭曲了心智的生物之间的联系。$B$B或许……如果我们对这些东西能有足够的了解，我们就能阻止血精灵步他们的后尘，走向堕落的深渊。' WHERE `entry` = 1275 AND `RequestItemsText_loc4` = '只要我有了足够的样本，就可以开始真正的研究了。有了这些从黑暗深渊里找到的萨特和纳迦的脑干，我就能找出这两种被魔法扭曲了心智的生物之间的联系。$B$B或许……如果我们对这些东西能有足够的了解，我们就能阻止血精灵步他们的後尘，走向堕落的深渊。';
