UPDATE `locales_quest` SET `RequestItemsText_loc4` = '滚!玛格拉姆不和弱者交谈!我们只会杀了他们!$B$B如果你想和我谈话，就先让我看看你有多强大!去杀更多的吉尔吉斯人，然后再回来!' WHERE `entry` = 1367 AND `RequestItemsText_loc4` = '滚!玛格拉姆不和弱者交谈!我们只会杀了他们!$B$B如果你想和我谈话，就先让我看看你有多强大!去杀更多的吉尔吉斯人，然後再回来!';
