UPDATE `locales_quest` SET `RequestItemsText_loc4` = '走开!吉尔吉斯不想在这里看见你!!$B$B干掉更多玛格拉姆部族的家伙以后再回来，那时候我才会和你好好谈谈。' WHERE `entry` = 1382 AND `RequestItemsText_loc4` = '走开!吉尔吉斯不想在这里看见你!!$B$B干掉更多玛格拉姆部族的家伙以後再回来，那时候我才会和你好好谈谈。';
