UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你难道害怕科卡尔部族了吗?为什么不去杀了他们?也许你已经忘了该如何杀人了。赶快去给我杀了他们!' WHERE `entry` = 1386 AND `RequestItemsText_loc4` = '你难道害怕科卡尔部族了吗?为什麽不去杀了他们?也许你已经忘了该如何杀人了。赶快去给我杀了他们!';
