UPDATE `locales_quest` SET `RequestItemsText_loc4` = '那些新兵们带着的羽毛符咒使他们拥有了一些魔法力量，研究它们是件有趣的事情，但是这些蠢货也只有这么点魔法能力了。' WHERE `entry` = 1599 AND `RequestItemsText_loc4` = '那些新兵们带着的羽毛符咒使他们拥有了一些魔法力量，研究它们是件有趣的事情，但是这些蠢货也只有这麽点魔法能力了。';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '但愿我丈夫约翰在铁炉堡能有更好的运气。他并不想把我和孩子们留下，自己一个人跑去那儿，不过他知道必须这么做，他真是太善良了。$B$B前些年的生活还不错，不过现在的日子越来越难过了。我们都能感觉到好像会有重大的变化发生，不过又有谁知道呢?' WHERE `entry` = 1644 AND `RequestItemsText_loc4` = '但愿我丈夫约翰在铁炉堡能有更好的运气。他并不想把我和孩子们留下，自己一个人跑去那儿，不过他知道必须这麽做，他真是太善良了。$B$B前些年的生活还不错，不过现在的日子越来越难过了。我们都能感觉到好像会有重大的变化发生，不过又有谁知道呢?';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '就算是这里和整个艾泽拉斯的商人都愿意帮忙，我们也无法得到足够的材料为孤儿院的所有孩子们制作衣裳。请帮我收集一些亚麻布，好让我的妻子力所能及地帮助孩子们。谢谢您，$N。$B$B如果走运的话，不久之后我就能回家见到我的妻子了。' WHERE `entry` = 1648 AND `RequestItemsText_loc4` = '就算是这里和整个艾泽拉斯的商人都愿意帮忙，我们也无法得到足够的材料为孤儿院的所有孩子们制作衣裳。请帮我收集一些亚麻布，好让我的妻子力所能及地帮助孩子们。谢谢您，$N。$B$B如果走运的话，不久之後我就能回家见到我的妻子了。';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '这些材料很难找到，不过我可以向你保证，我为你制造的武器绝对值得你这么做。$B$B这将是我目前为止最出色的作品，是送给你当作回报的。' WHERE `entry` = 1654 AND `RequestItemsText_loc4` = '这些材料很难找到，不过我可以向你保证，我为你制造的武器绝对值得你这麽做。$B$B这将是我目前为止最出色的作品，是送给你当作回报的。';
