UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你好，年轻人，我能为你做点什么吗?$B$B从台地走到这里对某些人来说可实在是极大的负担，不过对另一些人则是开阔眼界的好机会。我想知道你是这两种人里的哪一种?' WHERE `entry` = 1656 AND `RequestItemsText_loc4` = '你好，年轻人，我能为你做点什麽吗?$B$B从台地走到这里对某些人来说可实在是极大的负担，不过对另一些人则是开阔眼界的好机会。我想知道你是这两种人里的哪一种?';
