UPDATE `locales_quest` SET `RequestItemsText_loc4` = '$N，如果你来这里是来核实我交给你的任务，那么，很好─我要的是十块憎世纳迦的鳞片。如果你来这里是为了闲聊，那么现在我没空和你多罗嗦。$B$B要知道，我们夜精灵不是好战分子，我们致力于维护和平与安宁，但这并不代表我们会放弃维护自己的利益。这是我对羽月将军和这座要塞应尽的职责。' WHERE `entry` = 2869 AND `RequestItemsText_loc4` = '$N，如果你来这里是来核实我交给你的任务，那麽，很好─我要的是十块憎世纳迦的鳞片。如果你来这里是为了闲聊，那麽现在我没空和你多罗嗦。$B$B要知道，我们夜精灵不是好战分子，我们致力於维护和平与安宁，但这并不代表我们会放弃维护自己的利益。这是我对羽月将军和这座要塞应尽的职责。';
