UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你面前的地精装置上面钉着一张金属铭牌，上面写着「超级清洁器5200型」。阅读了铭牌上的说明之后，你发现这台机器是用来清洗污垢的，它是一个投币装置，将想要清洁的物体放入其中，然后投三枚银币，机器就会启动。$B$B你前不久发现的那枚脏兮兮的戒指正好可以用来试试看!' WHERE `entry` = 2945 AND `RequestItemsText_loc4` = '你面前的地精装置上面钉着一张金属铭牌，上面写着「超级清洁器5200型」。阅读了铭牌上的说明之後，你发现这台机器是用来清洗污垢的，它是一个投币装置，将想要清洁的物体放入其中，然後投三枚银币，机器就会启动。$B$B你前不久发现的那枚脏兮兮的戒指正好可以用来试试看!';
