UPDATE `locales_quest` SET `RequestItemsText_loc4` = '嘿，朋友，放轻松点─我是个有头有脸的商人!肯定是邮差忘了把帐单给我送来……等等……你不是我的房东。$B$B好吧，你当然不是来耍我的!你是来寻找铁炉堡最好的珠宝商的吧，我可绝对不会制作被诅咒的珠宝哦!绝对不会!$B$B嗯……你需要什么?' WHERE `entry` = 2947 AND `RequestItemsText_loc4` = '嘿，朋友，放轻松点─我是个有头有脸的商人!肯定是邮差忘了把帐单给我送来……等等……你不是我的房东。$B$B好吧，你当然不是来耍我的!你是来寻找铁炉堡最好的珠宝商的吧，我可绝对不会制作被诅咒的珠宝哦!绝对不会!$B$B嗯……你需要什麽?';
