UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你好，孩子。我们为越来越多强大的冒险者来到神殿感到由衷的高兴。如果你有时间的话，能和其他年轻的冒险者们分享一下你的故事吗?我相信这样对他们会有很大的帮助。$B$B对不起，请原谅我的鲁莽。你应该是到神殿里来寻求帮助的，我失礼了。请你原谅。我能为你做些什么?' WHERE `entry` = 2972 AND `RequestItemsText_loc4` = '你好，孩子。我们为越来越多强大的冒险者来到神殿感到由衷的高兴。如果你有时间的话，能和其他年轻的冒险者们分享一下你的故事吗?我相信这样对他们会有很大的帮助。$B$B对不起，请原谅我的鲁莽。你应该是到神殿里来寻求帮助的，我失礼了。请你原谅。我能为你做些什麽?';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '被激怒的小精龙是非常危险的，和它们打交道要多加小心，$C。这个地区的夜精灵比它们还危险，那些烦人的蠢货也会在森林里出没。$B$B当你拿到足够多的翅膀之后就告诉我，我一定会好好奖励你的!' WHERE `entry` = 2973 AND `RequestItemsText_loc4` = '被激怒的小精龙是非常危险的，和它们打交道要多加小心，$C。这个地区的夜精灵比它们还危险，那些烦人的蠢货也会在森林里出没。$B$B当你拿到足够多的翅膀之後就告诉我，我一定会好好奖励你的!';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '这是什么?' WHERE `entry` = 2978 AND `RequestItemsText_loc4` = '这是什麽?';
