UPDATE `locales_quest` SET `RequestItemsText_loc4` = '什么?什么?我能帮你什么忙吗，$C?心灵传送?神秘的知识?对贫瘠之地的部落发动突袭?我可是个多才多艺的强者，而且经验丰富。告诉我要怎么帮你吧。$B$B等一下，你在我的房间里干什么?!我可没邀请你进来!' WHERE `entry` = 3448 AND `RequestItemsText_loc4` = '什麽?什麽?我能帮你什麽忙吗，$C?心灵传送?神秘的知识?对贫瘠之地的部落发动突袭?我可是个多才多艺的强者，而且经验丰富。告诉我要怎麽帮你吧。$B$B等一下，你在我的房间里干什麽?!我可没邀请你进来!';
