UPDATE `locales_quest` SET `RequestItemsText_loc4` = '我要你收集的石板能让我们发一笔小财，当你找到它们之后，我会告诉你把它们送往何处的。但是，我可不是蠢货……我只有在确定它们都已送达的情况下才会把你应得的那一份给你。$B$B出发吧─我们的时间不多。我也许得多找些人来帮我。' WHERE `entry` = 3517 AND `RequestItemsText_loc4` = '我要你收集的石板能让我们发一笔小财，当你找到它们之後，我会告诉你把它们送往何处的。但是，我可不是蠢货……我只有在确定它们都已送达的情况下才会把你应得的那一份给你。$B$B出发吧─我们的时间不多。我也许得多找些人来帮我。';
