UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你跟杰斯雷蒙谈过了吗?$B$B他跟其他食人妖比起来简直像头猪，但是他的资讯通常都很正确，而且他给的报酬也很丰厚。$B$B如果你能忍受他的态度，那么也许你能从他那赚一大笔钱。' WHERE `entry` = 3563 AND `RequestItemsText_loc4` = '你跟杰斯雷蒙谈过了吗?$B$B他跟其他食人妖比起来简直像头猪，但是他的资讯通常都很正确，而且他给的报酬也很丰厚。$B$B如果你能忍受他的态度，那麽也许你能从他那赚一大笔钱。';
