UPDATE `locales_quest` SET `RequestItemsText_loc4` = '如果你随身带着塞纳里奥信标，那么你在采矿的时候就会看到那些污染了矿脉的硫酸盐。我可以对那些硫酸盐进行净化，然后把它们制成塞纳里奥植物药膏。你可以用这种药膏来拯救堕落的大自然。$B$B给我弄些受污染的硫酸盐来，我就可以给你几份药膏。' WHERE `entry` = 4104 AND `RequestItemsText_loc4` = '如果你随身带着塞纳里奥信标，那麽你在采矿的时候就会看到那些污染了矿脉的硫酸盐。我可以对那些硫酸盐进行净化，然後把它们制成塞纳里奥植物药膏。你可以用这种药膏来拯救堕落的大自然。$B$B给我弄些受污染的硫酸盐来，我就可以给你几份药膏。';
