UPDATE `locales_quest` SET `RequestItemsText_loc4` = '当你走向达丹加的时候，她目不转睛地看着你。她似乎在希望你拿给她什么东西……$B$B她也许是饿了!$B$B也许在环形山里长着一些可以喂给这头大型食草动物的花花草草。达丹加的个头不小，不管你准备给她喂什么，数量肯定少不了!' WHERE `entry` = 5150 AND `RequestItemsText_loc4` = '当你走向达丹加的时候，她目不转睛地看着你。她似乎在希望你拿给她什麽东西……$B$B她也许是饿了!$B$B也许在环形山里长着一些可以喂给这头大型食草动物的花花草草。达丹加的个头不小，不管你准备给她喂什麽，数量肯定少不了!';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你的战斗进行得怎么样了，$N?我知道把挥洒的鲜血作为荣誉的证明让有些人感到疑惑，但是你必须懂得这么做的原因:它可以让我的任务变得简单一些。另一方面，我们可以因此而互相尊重。$B$B我希望你能懂得这些。' WHERE `entry` = 5155 AND `RequestItemsText_loc4` = '你的战斗进行得怎麽样了，$N?我知道把挥洒的鲜血作为荣誉的证明让有些人感到疑惑，但是你必须懂得这麽做的原因:它可以让我的任务变得简单一些。另一方面，我们可以因此而互相尊重。$B$B我希望你能懂得这些。';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '一旦我们有了月井的水，就可以对其进行净化，然后用它来熄灭保护暗影堡的火盆。这样我就有充足的时间来侦测他们的老巢，并搞清楚是谁在领导着他们……$B$B我希望大地之母能与我们同在。' WHERE `entry` = 5157 AND `RequestItemsText_loc4` = '一旦我们有了月井的水，就可以对其进行净化，然後用它来熄灭保护暗影堡的火盆。这样我就有充足的时间来侦测他们的老巢，并搞清楚是谁在领导着他们……$B$B我希望大地之母能与我们同在。';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '真想知道我的朋友会有什么反应!$B$B他们绝对会被吓一大跳的!' WHERE `entry` = 5163 AND `RequestItemsText_loc4` = '真想知道我的朋友会有什麽反应!$B$B他们绝对会被吓一大跳的!';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '如果我们想要发动一场大战的话，那些火盆就必须被熄灭。毫无准备地闯入暗影堡无异于找死。现在我们所面对的敌人甚至比一条龙还要危险─暗影议会犯下了无数滔天的罪行。如果我们要阻止他们的话，就必须快点行动了。' WHERE `entry` = 5165 AND `RequestItemsText_loc4` = '如果我们想要发动一场大战的话，那些火盆就必须被熄灭。毫无准备地闯入暗影堡无异於找死。现在我们所面对的敌人甚至比一条龙还要危险─暗影议会犯下了无数滔天的罪行。如果我们要阻止他们的话，就必须快点行动了。';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你检查了那具尸体，毫无疑问，这就是白银之手骑士团的特雷·莱弗治的遗体了。你想起了亚科纳琳，并想起了这位圣骑士的死对她所造成的打击。$B$B过了一会儿，你重新收回了思绪。你很清楚，在没有杀死折磨这个圣骑士的恶徒之前，你是无法把他的遗体带回杰希尔那里的。' WHERE `entry` = 5204 AND `RequestItemsText_loc4` = '你检查了那具屍体，毫无疑问，这就是白银之手骑士团的特雷·莱弗治的遗体了。你想起了亚科纳琳，并想起了这位圣骑士的死对她所造成的打击。$B$B过了一会儿，你重新收回了思绪。你很清楚，在没有杀死折磨这个圣骑士的恶徒之前，你是无法把他的遗体带回杰希尔那里的。';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你从西边来的?罗德隆的其他人怎么样了?我知道安多哈尔已经陷落了，但是天谴军团到达美丽的提里斯法了吗?' WHERE `entry` = 5210 AND `RequestItemsText_loc4` = '你从西边来的?罗德隆的其他人怎麽样了?我知道安多哈尔已经陷落了，但是天谴军团到达美丽的提里斯法了吗?';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '欢迎回到相对来说还算安全的亡灵壁垒，$N。你在瘟疫之锅那边有什么进展要汇报吗?' WHERE `entry` = 5230 AND `RequestItemsText_loc4` = '欢迎回到相对来说还算安全的亡灵壁垒，$N。你在瘟疫之锅那边有什麽进展要汇报吗?';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '盖罗恩农场的瘟疫之锅是我们在西瘟疫之地的最后一个目标。只要我们得到锅中的瘟疫样本，我们就可以通过这四口锅把我们的解药散播到空气中!即使有科尔苏加德的支持，天谴军团也很难兼顾四口瘟疫之锅。' WHERE `entry` = 5236 AND `RequestItemsText_loc4` = '盖罗恩农场的瘟疫之锅是我们在西瘟疫之地的最後一个目标。只要我们得到锅中的瘟疫样本，我们就可以通过这四口锅把我们的解药散播到空气中!即使有科尔苏加德的支持，天谴军团也很难兼顾四口瘟疫之锅。';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你要注意，并不是所有的补给木箱都在城市被毁灭后保存了下来。天谴军团不敢碰触圣水，但圣水并不能阻止害虫的侵袭。' WHERE `entry` = 5243 AND `RequestItemsText_loc4` = '你要注意，并不是所有的补给木箱都在城市被毁灭後保存了下来。天谴军团不敢碰触圣水，但圣水并不能阻止害虫的侵袭。';
