UPDATE `locales_quest` SET `RequestItemsText_loc4` = '啊，没什么比一双巧手更有价值的了，你只需看看护甲的线脚，就可以知道它是个什么级别的货色。' WHERE `entry` = 5283 AND `RequestItemsText_loc4` = '啊，没什麽比一双巧手更有价值的了，你只需看看护甲的线脚，就可以知道它是个什麽级别的货色。';
