UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你带来了什么消息，$C?啊—你是说我兄弟托送的消息?好吧，把报告给我吧!' WHERE `entry` = 5361 AND `RequestItemsText_loc4` = '你带来了什麽消息，$C?啊—你是说我兄弟托送的消息?好吧，把报告给我吧!';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '加德纳尔的情况怎么样了，$N?' WHERE `entry` = 5385 AND `RequestItemsText_loc4` = '加德纳尔的情况怎麽样了，$N?';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '爪牙的天谴石是天谴军团的身份象征，通常是由那些部署在瘟疫之地的、较为弱小的士兵所携带的。我所说的「较为弱小」是个相对的概念，无论天谴军团出现在哪里，他们都是一个不可轻视的威胁。$B$B如果你能拿来二十个这样的天谴石，银色黎明将会给你颁发一枚勇气徽记，以此表彰你在于天谴军团的战争中做出的贡献!' WHERE `entry` = 5402 AND `RequestItemsText_loc4` = '爪牙的天谴石是天谴军团的身份象徵，通常是由那些部署在瘟疫之地的、较为弱小的士兵所携带的。我所说的「较为弱小」是个相对的概念，无论天谴军团出现在哪里，他们都是一个不可轻视的威胁。$B$B如果你能拿来二十个这样的天谴石，银色黎明将会给你颁发一枚勇气徽记，以此表彰你在於天谴军团的战争中做出的贡献!';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '侵略者的天谴石是天谴军团精英部队的象征，通常是由那些部署在瘟疫之地的主力部队中的士兵携带的。斩杀这样的敌人对你来说是一个挑战，但是你也会因此得到丰厚的奖赏。$B$B如果你能拿来十块这样的天谴石，银色黎明就将给你颁发一枚勇气徽记。' WHERE `entry` = 5403 AND `RequestItemsText_loc4` = '侵略者的天谴石是天谴军团精英部队的象徵，通常是由那些部署在瘟疫之地的主力部队中的士兵携带的。斩杀这样的敌人对你来说是一个挑战，但是你也会因此得到丰厚的奖赏。$B$B如果你能拿来十块这样的天谴石，银色黎明就将给你颁发一枚勇气徽记。';
