UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你找到什么东西了吗，$N?我想知道为什么她的族人要做出无谓的牺牲，任何有关的线索都会对我们很有帮助的。' WHERE `entry` = 5724 AND `RequestItemsText_loc4` = '你找到什麽东西了吗，$N?我想知道为什麽她的族人要做出无谓的牺牲，任何有关的线索都会对我们很有帮助的。';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你拿到了徽记吗，$N?$B$B它将是你渗透到火刃氏族中去的重要工具，我认为他们是部落的最大威胁，也是我们刚刚得到的和平的最大威胁。$B$B你会发现，当人类或是兽人受到贪欲和权力驱使时，他们会干出多么可怕的事情来。那些阴暗的勾当和隐藏的敌人终将露出真面目来。你将发现自己置身于一场你从未想像过的战争中。' WHERE `entry` = 5726 AND `RequestItemsText_loc4` = '你拿到了徽记吗，$N?$B$B它将是你渗透到火刃氏族中去的重要工具，我认为他们是部落的最大威胁，也是我们刚刚得到的和平的最大威胁。$B$B你会发现，当人类或是兽人受到贪欲和权力驱使时，他们会干出多麽可怕的事情来。那些阴暗的勾当和隐藏的敌人终将露出真面目来。你将发现自己置身於一场你从未想像过的战争中。';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '嗯，$C?他相信我们了没有?要不然就是事情比预计的更加糟糕?$B$B向尼尔鲁证明你的价值，这样我们就更容易进入暗影议会。我们可以利用他提供的大量情报找到真正的幕后主使。' WHERE `entry` = 5727 AND `RequestItemsText_loc4` = '嗯，$C?他相信我们了没有?要不然就是事情比预计的更加糟糕?$B$B向尼尔鲁证明你的价值，这样我们就更容易进入暗影议会。我们可以利用他提供的大量情报找到真正的幕後主使。';
