UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你铸造出骷髅钥匙的主体部分了吗?很抱歉你得自己掏钱来买这个模具，但是我们必须各尽所能地共同对抗天谴军团。一旦你把未完成的钥匙交给我，你就可以开始准备铸造钥匙所需的最后一件物品了。$B$B虽然这并不简单，但是你为了进攻安多哈尔所做的准备将会初见成效。你会看到的。' WHERE `entry` = 5801 AND `RequestItemsText_loc4` = '你铸造出骷髅钥匙的主体部分了吗?很抱歉你得自己掏钱来买这个模具，但是我们必须各尽所能地共同对抗天谴军团。一旦你把未完成的钥匙交给我，你就可以开始准备铸造钥匙所需的最後一件物品了。$B$B虽然这并不简单，但是你为了进攻安多哈尔所做的准备将会初见成效。你会看到的。';
