UPDATE `locales_quest` SET `RequestItemsText_loc4` = '你拿到那野兽的爪子了吗，$N?它会为它的罪行付出代价的。我不管它是堕落了还是仅仅因为生活在这片阴暗的森林中而感到愤怒。任何熊怪都不能在对我的家庭犯下这种恶行之后逍遥法外!' WHERE `entry` = 6162 AND `RequestItemsText_loc4` = '你拿到那野兽的爪子了吗，$N?它会为它的罪行付出代价的。我不管它是堕落了还是仅仅因为生活在这片阴暗的森林中而感到愤怒。任何熊怪都不能在对我的家庭犯下这种恶行之後逍遥法外!';
