UPDATE `locales_quest` SET `RequestItemsText_loc4` = '血怒撕裂者是个肮脏的生物!你可以在焦炭谷西部的山岭中找到她。$B$B只要干掉了她，血怒鹰身人就会乱作一团……然后我们就可以把它们完全消灭掉!' WHERE `entry` = 6283 AND `RequestItemsText_loc4` = '血怒撕裂者是个肮脏的生物!你可以在焦炭谷西部的山岭中找到她。$B$B只要干掉了她，血怒鹰身人就会乱作一团……然後我们就可以把它们完全消灭掉!';
