UPDATE `locales_quest` SET `RequestItemsText_loc4` = '$N，感谢你所给予我的一切帮助。我实在无法足够的表达我的谢意!$B$B虽然我没那么需要了……但是如果你带给我更多的致密砂轮，我可以给你更多暗月马戏团奖券。' WHERE `entry` = 7939 AND `RequestItemsText_loc4` = '$N，感谢你所给予我的一切帮助。我实在无法足够的表达我的谢意!$B$B虽然我没那麽需要了……但是如果你带给我更多的致密砂轮，我可以给你更多暗月马戏团奖券。';
UPDATE `locales_quest` SET `RequestItemsText_loc4` = '$N，你对我们真是太好了，一直不嫌疲倦的替我带来这些货物。我由衷的感谢你!$B$B虽然我们对于瑟银零件的需求已经不像之前那么大了，但是你仍然可以拿来给我，我还是会很乐意用它们来交换暗月马戏团奖券的。' WHERE `entry` = 7942 AND `RequestItemsText_loc4` = '$N，你对我们真是太好了，一直不嫌疲倦的替我带来这些货物。我由衷的感谢你!$B$B虽然我们对於瑟银零件的需求已经不像之前那麽大了，但是你仍然可以拿来给我，我还是会很乐意用它们来交换暗月马戏团奖券的。';
