UPDATE `locales_quest` SET `RequestItemsText_loc4` = '牧师，你与古拉巴什一族作战的英勇事迹早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。' WHERE `entry` = 8049 AND `RequestItemsText_loc4` = '牧师，你与古拉巴什一族作战的英勇事蹟早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。';
