UPDATE `locales_page_text` SET `Text_loc4` = '艾耶克和艾尔加丁爵士悄无声息地用枪瞄准着正在晃动的树丛。正午的强烈阳光照在我们身上，当艾尔加丁爵士终于扣动扳机的时候，他的额头流下了一丝汗水。一声枪响过后，浓密的树叶被打得乱飞，一只非常漂亮的大黑豹向离弦的箭一般冲向了平原。' WHERE `entry` = 110 AND `Text_loc4` = '艾耶克和艾尔加丁爵士悄无声息地用枪瞄准着正在晃动的树丛。正午的强烈阳光照在我们身上，当艾尔加丁爵士终於扣动扳机的时候，他的额头流下了一丝汗水。一声枪响过後，浓密的树叶被打得乱飞，一只非常漂亮的大黑豹向离弦的箭一般冲向了平原。';
