UPDATE `locales_page_text` SET `Text_loc4` = '他的枪重重地击在他的肩膀上，枪管歪向一边，正好落在艾耶克的枪下面。艾耶克瞄准树冠适时地扣动了扳机，一声清晰的枪响过后，树冠上的一群鸟尖叫着四处飞散，树上冒出了一阵烟，我们惊异地看到一根巨大的树枝掉落下来，正好砸中了疾驰的黑豹。' WHERE `entry` = 112 AND `Text_loc4` = '他的枪重重地击在他的肩膀上，枪管歪向一边，正好落在艾耶克的枪下面。艾耶克瞄准树冠适时地扣动了扳机，一声清晰的枪响过後，树冠上的一群鸟尖叫着四处飞散，树上冒出了一阵烟，我们惊异地看到一根巨大的树枝掉落下来，正好砸中了疾驰的黑豹。';
