UPDATE `locales_page_text` SET `Text_loc4` = '我举着枪缓缓地前进。是我将这些勇敢的猎人带向了死亡的边缘，我至死都要保护他们!鞭尾迅猛龙异常凶残，它们一向都以残酷嗜血而闻名，而且现在它们的数量远远多于我们。但是，我决不能就让这些野兽轻易地杀了我和我的同伴。' WHERE `entry` = 120 AND `Text_loc4` = '我举着枪缓缓地前进。是我将这些勇敢的猎人带向了死亡的边缘，我至死都要保护他们!鞭尾迅猛龙异常凶残，它们一向都以残酷嗜血而闻名，而且现在它们的数量远远多於我们。但是，我决不能就让这些野兽轻易地杀了我和我的同伴。';
UPDATE `locales_page_text` SET `Text_loc4` = '艾耶克和艾尔加丁爵士拿起他们的武器，守在我的两侧，我们的背后就是大海。巴尼尔沮丧地叹了一口长气，然后拿起了他的斧头。迅猛龙在慢慢地逼近，它们高傲地注视着我们，因为它们知道我们已经无路可逃了。' WHERE `entry` = 121 AND `Text_loc4` = '艾耶克和艾尔加丁爵士拿起他们的武器，守在我的两侧，我们的背後就是大海。巴尼尔沮丧地叹了一口长气，然後拿起了他的斧头。迅猛龙在慢慢地逼近，它们高傲地注视着我们，因为它们知道我们已经无路可逃了。';
