UPDATE `locales_page_text` SET `Text_loc4` = '过了几个星期，我们的豹皮和虎皮储备已经相当充足了。于是我决定将探险队的注意力转向一个新的挑战:迅猛龙。$B$B队伍中的两个人类虽然十分感激我和巴尼尔对他们进行的训练，不过他们还是决定不使用我们提供的火枪去打猎。艾耶克更喜欢她那调校完美的强弓，而艾尔加丁爵士离开营地的时候总是拿着他的弩。' WHERE `entry` = 171 AND `Text_loc4` = '过了几个星期，我们的豹皮和虎皮储备已经相当充足了。於是我决定将探险队的注意力转向一个新的挑战:迅猛龙。$B$B队伍中的两个人类虽然十分感激我和巴尼尔对他们进行的训练，不过他们还是决定不使用我们提供的火枪去打猎。艾耶克更喜欢她那调校完美的强弓，而艾尔加丁爵士离开营地的时候总是拿着他的弩。';
