UPDATE `locales_page_text` SET `Text_loc4` = '这不是一个普通战士的妻子应该提的问题。$B$B然而我现在是作为一个普通战士的遗孀给您写这些的。我的丈夫只是您成千上万个士兵中的一员，而对于我来说，他就是伟大的苏利·巴鲁，是我孩子的父亲，是我心爱的丈夫，是要和厮守终生的伴侣。$B$B伟大的陛下，如果我的问题对您不敬，请原谅我。但是逝者已经不能亲自来问这些问题了……$B$B您忠诚的臣民，$B萨拉·巴鲁' WHERE `entry` = 335 AND `Text_loc4` = '这不是一个普通战士的妻子应该提的问题。$B$B然而我现在是作为一个普通战士的遗孀给您写这些的。我的丈夫只是您成千上万个士兵中的一员，而对於我来说，他就是伟大的苏利·巴鲁，是我孩子的父亲，是我心爱的丈夫，是要和厮守终生的伴侣。$B$B伟大的陛下，如果我的问题对您不敬，请原谅我。但是逝者已经不能亲自来问这些问题了……$B$B您忠诚的臣民，$B萨拉·巴鲁';
UPDATE `locales_page_text` SET `Text_loc4` = '同时，我还派出了阿维罗德上尉，在卡林多大陆执行侦察任务。他的部队完成任务之后，会与我们在提拉加德城堡的部队会合。$B$B阿维罗德上尉的任务可能需要很长时间，因为这片新大陆幅员辽阔、充满危机。如果我或者本尼迪克遭遇不幸的话，阿维罗德将接手城堡的指挥权。$B$B我们会发动一轮接一轮的攻击，直到占领这座要塞!$B$B- 普劳德摩尔上将' WHERE `entry` = 338 AND `Text_loc4` = '同时，我还派出了阿维罗德上尉，在卡林多大陆执行侦察任务。他的部队完成任务之後，会与我们在提拉加德城堡的部队会合。$B$B阿维罗德上尉的任务可能需要很长时间，因为这片新大陆幅员辽阔、充满危机。如果我或者本尼迪克遭遇不幸的话，阿维罗德将接手城堡的指挥权。$B$B我们会发动一轮接一轮的攻击，直到占领这座要塞!$B$B- 普劳德摩尔上将';
