UPDATE `locales_page_text` SET `Text_loc4` = '部落征兵通知$B$B持此通知者已被证明具备出众的力量和战斗技巧。我建议将其分派到十字路口去执行任务。$B$B- 塔克林·寻路者谨上' WHERE `entry` = 340 AND `Text_loc4` = '部落徵兵通知$B$B持此通知者已被证明具备出众的力量和战斗技巧。我建议将其分派到十字路口去执行任务。$B$B- 塔克林·寻路者谨上';
