UPDATE `locales_page_text` SET `Text_loc4` = '我们的侦察员继续搜索时，在伊瓦的农场遭遇了伏击。伊瓦和他的家人，还有他的工人们，都成了天谴军团的爪牙。$B$B我们的侦察员遭到他们的袭击，虽然最后成功地击退了伏兵，但是均身负重伤，尤其是奎恩。' WHERE `entry` = 382 AND `Text_loc4` = '我们的侦察员继续搜索时，在伊瓦的农场遭遇了伏击。伊瓦和他的家人，还有他的工人们，都成了天谴军团的爪牙。$B$B我们的侦察员遭到他们的袭击，虽然最後成功地击退了伏兵，但是均身负重伤，尤其是奎恩。';
UPDATE `locales_page_text` SET `Text_loc4` = '他们在伊瓦的旧房子里设置了一处防守点，兰妮负责警戒工作，埃兰德则继续侦察任务。$B$B埃兰德在北边的一座果园中被狼人困住，后来在一个被遗忘者密探的帮助下才得以逃脱─也就是向您递交这份报告的信差。' WHERE `entry` = 383 AND `Text_loc4` = '他们在伊瓦的旧房子里设置了一处防守点，兰妮负责警戒工作，埃兰德则继续侦察任务。$B$B埃兰德在北边的一座果园中被狼人困住，後来在一个被遗忘者密探的帮助下才得以逃脱─也就是向您递交这份报告的信差。';
