UPDATE `locales_page_text` SET `Text_loc4` = '赫格拉姆，$B$B无论是谁提议，在荒芜之地的卡加斯建立一片基地，都将得到我的赞同。这个计画将使我们在那里拥有常备的驻军。那里的天气很糟，到处都是凶恶的野生动物与好战的土着，也没有什么补给，惟有我们最好的战士与斥候，可以在那里立足。$B$B这计画很好。干得漂亮。' WHERE `entry` = 711 AND `Text_loc4` = '赫格拉姆，$B$B无论是谁提议，在荒芜之地的卡加斯建立一片基地，都将得到我的赞同。这个计画将使我们在那里拥有常备的驻军。那里的天气很糟，到处都是凶恶的野生动物与好战的土着，也没有什麽补给，惟有我们最好的战士与斥候，可以在那里立足。$B$B这计画很好。干得漂亮。';
