UPDATE `locales_page_text` SET `Text_loc4` = '尼尔斯修士:$B$B我的葡萄得救了!$N，也就是这封信的携带者，勇敢地闯入我那满是盗贼的园子，然后带着我的葡萄杀了出来。虽然迪菲亚兄弟会的人依然在河岸上巡逻，但是我所有的收成几乎全都保住了。$B$B你可以在你的商店中再次供应葡萄了。$B$B愿圣光保佑我们，$B- 米莉·奥斯沃斯' WHERE `entry` = 1392 AND `Text_loc4` = '尼尔斯修士:$B$B我的葡萄得救了!$N，也就是这封信的携带者，勇敢地闯入我那满是盗贼的园子，然後带着我的葡萄杀了出来。虽然迪菲亚兄弟会的人依然在河岸上巡逻，但是我所有的收成几乎全都保住了。$B$B你可以在你的商店中再次供应葡萄了。$B$B愿圣光保佑我们，$B- 米莉·奥斯沃斯';
