UPDATE `locales_page_text` SET `Text_loc4` = '罗德隆的最后一位国王，泰瑞纳斯·米奈希尔二世在此长眠。$B$B他的一生做出了无数伟大的功绩，他的陨落令人扼腕叹息。$B$B         「愿这位父王宽恕其子嗣所做的一切。$B          愿血染的王冠永远被遗失和忘却。」' WHERE `entry` = 1731 AND `Text_loc4` = '罗德隆的最後一位国王，泰瑞纳斯·米奈希尔二世在此长眠。$B$B他的一生做出了无数伟大的功绩，他的陨落令人扼腕叹息。$B$B         「愿这位父王宽恕其子嗣所做的一切。$B          愿血染的王冠永远被遗失和忘却。」';
