UPDATE `locales_page_text` SET `Text_loc4` = '『劫毁者』霍古斯的命运$B$B『劫毁者』霍古斯在达隆郡之战中阵亡。但是他身上的邪恶气息仍然存在。获胜的天谴军团将他的头颅从达隆郡的废墟中带走，用其在仍然活着的生灵中散播恐惧的气氛。$B$B几天之后，这群拿着头颅的天谴军团士兵被白银之手骑士团击溃，霍古斯的头颅也被扔入了黑木湖中。' WHERE `entry` = 2383 AND `Text_loc4` = '『劫毁者』霍古斯的命运$B$B『劫毁者』霍古斯在达隆郡之战中阵亡。但是他身上的邪恶气息仍然存在。获胜的天谴军团将他的头颅从达隆郡的废墟中带走，用其在仍然活着的生灵中散播恐惧的气氛。$B$B几天之後，这群拿着头颅的天谴军团士兵被白银之手骑士团击溃，霍古斯的头颅也被扔入了黑木湖中。';
UPDATE `locales_page_text` SET `Text_loc4` = '达维·莱法尔的命运$B$B达维·莱法尔在达隆郡之战中阵亡，但是他的英勇事迹鼓舞了整个联盟。$B$B他的圣骑士宝典被血色十字军所保管，现在存放在血色十字军控制的壁炉谷城镇大厅中，经常被那些崇敬他的十字军成员争相阅读。' WHERE `entry` = 2385 AND `Text_loc4` = '达维·莱法尔的命运$B$B达维·莱法尔在达隆郡之战中阵亡，但是他的英勇事蹟鼓舞了整个联盟。$B$B他的圣骑士宝典被血色十字军所保管，现在存放在血色十字军控制的壁炉谷城镇大厅中，经常被那些崇敬他的十字军成员争相阅读。';
UPDATE `locales_page_text` SET `Text_loc4` = '卡林·雷德帕斯的命运$B$B约瑟夫·雷德帕斯队长的兄弟，卡林·雷德帕斯在达隆郡的战斗中倒下了，他身负重伤，但是最终侥幸活了下来。$B$B在大战过后的几天，银色黎明组织发现了奄奄一息的卡林·雷德帕斯，他又渴又累，而且还发着烧，倒在了考林的十字路口附近。他们治疗了他的伤势，并把他带到了圣光之愿礼拜堂。$B$B由于对银色黎明的感激之情，卡林·雷德帕斯加入了银色黎明，并为了复仇而与天谴军团展开战斗。' WHERE `entry` = 2391 AND `Text_loc4` = '卡林·雷德帕斯的命运$B$B约瑟夫·雷德帕斯队长的兄弟，卡林·雷德帕斯在达隆郡的战斗中倒下了，他身负重伤，但是最终侥幸活了下来。$B$B在大战过後的几天，银色黎明组织发现了奄奄一息的卡林·雷德帕斯，他又渴又累，而且还发着烧，倒在了考林的十字路口附近。他们治疗了他的伤势，并把他带到了圣光之愿礼拜堂。$B$B由於对银色黎明的感激之情，卡林·雷德帕斯加入了银色黎明，并为了复仇而与天谴军团展开战斗。';
