UPDATE `locales_page_text` SET `Text_loc4` = '要束缚恐惧战马，你必须做三件事:$B$B制造强力召唤法阵。$B$B在法阵中打开通往克索诺斯的传送门，将恐惧战马引入我们的世界。$B$B击败恐惧战马并控制它的灵魂。$B$B下一页将详细描述要如何执行这些步骤。这可不是一件容易的事，但是你是有能力完成它。只要集中精神运用你的所有技能，我相信恐惧战马会属于你的。$B$B继续读下去吧。$B- 莫苏尔·召血者' WHERE `entry` = 2691 AND `Text_loc4` = '要束缚恐惧战马，你必须做三件事:$B$B制造强力召唤法阵。$B$B在法阵中打开通往克索诺斯的传送门，将恐惧战马引入我们的世界。$B$B击败恐惧战马并控制它的灵魂。$B$B下一页将详细描述要如何执行这些步骤。这可不是一件容易的事，但是你是有能力完成它。只要集中精神运用你的所有技能，我相信恐惧战马会属於你的。$B$B继续读下去吧。$B- 莫苏尔·召血者';
UPDATE `locales_page_text` SET `Text_loc4` = '铃铛、车轮和蜡烛$B$B释放耶维尔之后，他将布置铃铛、车轮和蜡烛，为你构建法阵。仪式随即开始，你必须保持警惕，这些道具会引导出强大的魔法能量，而且很容易失效。在整个仪式失败之前，你必须快速使用黑色磁石来重新启动失效的道具。$B$B如果三件道具都失效的话，仪式也就失败了，你就不得不从头再来。' WHERE `entry` = 2694 AND `Text_loc4` = '铃铛、车轮和蜡烛$B$B释放耶维尔之後，他将布置铃铛、车轮和蜡烛，为你构建法阵。仪式随即开始，你必须保持警惕，这些道具会引导出强大的魔法能量，而且很容易失效。在整个仪式失败之前，你必须快速使用黑色磁石来重新启动失效的道具。$B$B如果三件道具都失效的话，仪式也就失败了，你就不得不从头再来。';
UPDATE `locales_page_text` SET `Text_loc4` = '用于重新启动铃铛、车轮和蜡烛的黑色磁石需要灵魂裂片方可生效，这点你需要牢记。每次使用黑石磁石启动一件仪式道具时，都需要消耗一片灵魂裂片。因此，在开始仪式之前，你必须收集大量的灵魂裂片。' WHERE `entry` = 2696 AND `Text_loc4` = '用於重新启动铃铛、车轮和蜡烛的黑色磁石需要灵魂裂片方可生效，这点你需要牢记。每次使用黑石磁石启动一件仪式道具时，都需要消耗一片灵魂裂片。因此，在开始仪式之前，你必须收集大量的灵魂裂片。';
UPDATE `locales_page_text` SET `Text_loc4` = '<HTML><BODY><P align="left">长眠于此的是霜狼氏族的第一任酋长，我们敬仰的部落酋长索尔的父亲 - 杜洛坦。他被那些想要让我们永远受到奴役的同胞背叛。杜洛坦为了我们的自由而献出了自己的生命，我们敬仰他，以及他留给我们的珍贵遗产，他伟大的儿子。' WHERE `entry` = 2731 AND `Text_loc4` = '<HTML><BODY><P align="left">长眠於此的是霜狼氏族的第一任酋长，我们敬仰的部落酋长索尔的父亲 - 杜洛坦。他被那些想要让我们永远受到奴役的同胞背叛。杜洛坦为了我们的自由而献出了自己的生命，我们敬仰他，以及他留给我们的珍贵遗产，他伟大的儿子。';
