UPDATE `locales_page_text` SET `Text_loc4` = '你很特别，不管你的朋友，亲戚，同事，路上的陌生人，或是你的良心是怎么告诉你的。' WHERE `entry` = 3016 AND `Text_loc4` = '你很特别，不管你的朋友，亲戚，同事，路上的陌生人，或是你的良心是怎麽告诉你的。';
UPDATE `locales_page_text` SET `Text_loc4` = '当我上一次在大厅里，鹰王伊奇斯身上带着泰洛克羽毛，做为他掌权的象征。他应该还带着它来说服他的追随者他是泰洛克复活。$B$B我的兄弟，暗法师希斯在进行塞司克仪式时会戴着泰洛克面罩。$B$B至于泰洛克的传说，它被保管在鹰王伊奇斯房间外的一个拱形房间里，在符文法阵里面。' WHERE `entry` = 3029 AND `Text_loc4` = '当我上一次在大厅里，鹰王伊奇斯身上带着泰洛克羽毛，做为他掌权的象徵。他应该还带着它来说服他的追随者他是泰洛克复活。$B$B我的兄弟，暗法师希斯在进行塞司克仪式时会戴着泰洛克面罩。$B$B至於泰洛克的传说，它被保管在鹰王伊奇斯房间外的一个拱形房间里，在符文法阵里面。';
UPDATE `locales_page_text` SET `Text_loc4` = '听着，霸德!$B$B这是最后一个我送去给你的傻瓜，除非你把欠债付清。$B$B不准再拖延了!$B$B格利夫塔' WHERE `entry` = 3031 AND `Text_loc4` = '听着，霸德!$B$B这是最後一个我送去给你的傻瓜，除非你把欠债付清。$B$B不准再拖延了!$B$B格利夫塔';
UPDATE `locales_page_text` SET `Text_loc4` = '加尔恩，$B$B我应该不需要提醒你，你的任务有多重要 -- 不计代价保护你珍贵的货物。如我所承诺过，成功与谨慎将会获得财富的回报。$B$B别对你的「伙伴」饶舌，看紧那些船员，那一切都会很顺利。我等着你成功的消息。' WHERE `entry` = 3032 AND `Text_loc4` = '加尔恩，$B$B我应该不需要提醒你，你的任务有多重要 -- 不计代价保护你珍贵的货物。如我所承诺过，成功与谨慎将会获得财富的回报。$B$B别对你的「夥伴」饶舌，看紧那些船员，那一切都会很顺利。我等着你成功的消息。';
UPDATE `locales_page_text` SET `Text_loc4` = '我送去了一批可观的武力给你，长老，但你一定要小心注意你的活动。你的首要目标就是终止联盟对我们土地的扩张。某些为数不少的人类已经开始在贫瘠之地的边境上构筑一个巨大建筑物。$B$B一定要让他们知道自己在可悲的塞拉摩边界之外并不受欢迎。最后，告诫你一句话，长老:别让你的计画给蕨墙村的那些巨魔知道。那些野蛮的东西连最低程度的谨慎都办不到。$B$B - 亚加席姆' WHERE `entry` = 3033 AND `Text_loc4` = '我送去了一批可观的武力给你，长老，但你一定要小心注意你的活动。你的首要目标就是终止联盟对我们土地的扩张。某些为数不少的人类已经开始在贫瘠之地的边境上构筑一个巨大建筑物。$B$B一定要让他们知道自己在可悲的塞拉摩边界之外并不受欢迎。最後，告诫你一句话，长老:别让你的计画给蕨墙村的那些巨魔知道。那些野蛮的东西连最低程度的谨慎都办不到。$B$B - 亚加席姆';
UPDATE `locales_page_text` SET `Text_loc4` = '奈普图隆的部下中，有个名叫艾胡恩的强大冰霜领主。至今他仍在聚集力量要对拉格纳罗斯掀起战争。他只需要一个通道来进入我们的世界；一个由我们提供的通道。我们有盟友，有地点。我们也有力量与意志。$B$B和我们忠诚的新盟友与客人之间的最后协商，将会在一个安全遥远的地方，在我们梣谷原始据点的西北边。$B$B在这个无知的「节庆」结束前，艾胡恩将会在黑石山的深处面对拉格纳罗斯。这个世界将会因为他们释放出来的力量而倾覆。$B$B我们一切的努力都是为了这一刻。我们的主人将会再次兴起，彼此征战，并且将艾泽拉斯撕裂成碎片。$B$B我们将会活在时间的终结，我的兄弟。肩负起你的任务。努力下去。我们终将获胜!' WHERE `entry` = 3066 AND `Text_loc4` = '奈普图隆的部下中，有个名叫艾胡恩的强大冰霜领主。至今他仍在聚集力量要对拉格纳罗斯掀起战争。他只需要一个通道来进入我们的世界；一个由我们提供的通道。我们有盟友，有地点。我们也有力量与意志。$B$B和我们忠诚的新盟友与客人之间的最後协商，将会在一个安全遥远的地方，在我们梣谷原始据点的西北边。$B$B在这个无知的「节庆」结束前，艾胡恩将会在黑石山的深处面对拉格纳罗斯。这个世界将会因为他们释放出来的力量而倾覆。$B$B我们一切的努力都是为了这一刻。我们的主人将会再次兴起，彼此征战，并且将艾泽拉斯撕裂成碎片。$B$B我们将会活在时间的终结，我的兄弟。肩负起你的任务。努力下去。我们终将获胜!';

