UPDATE `locales_broadcast_text` SET `male_text_loc4` = '人类在贫瘠之地的边界处建了一座旅店，他们叫它树荫旅店。几个星期前，这家旅店被烧掉了。$B$B关我什么事?我对人类不太了解，但我派了一个间谍在旅店内，我不会让他死的不明不白。我需要知道是谁干的。$B$B如果你想帮忙，就到树荫旅店的废墟查看，把任何你能找到的线索给带回来。' WHERE `entry` = 4260 AND `male_text_loc4` = '人类在贫瘠之地的边界处建了一座旅店，他们叫它树荫旅店。几个星期前，这家旅店被烧掉了。$B$B关我什麽事?我对人类不太了解，但我派了一个间谍在旅店内，我不会让他死的不明不白。我需要知道是谁干的。$B$B如果你想帮忙，就到树荫旅店的废墟查看，把任何你能找到的线索给带回来。';
