UPDATE `locales_broadcast_text` SET `male_text_loc4` = '$N，我已经查明魔苔在整个黑海岸的影响有多么的猖獗。泰达希尔和我们周围大地的堕落的确引起了塞纳里奥议会德鲁伊以及所有的夜精灵的关注。$B$B我的目标就是查出为什么会发生这样的事并将其制止。' WHERE `entry` = 5608 AND `male_text_loc4` = '$N，我已经查明魔苔在整个黑海岸的影响有多麽的猖獗。泰达希尔和我们周围大地的堕落的确引起了塞纳里奥议会德鲁伊以及所有的夜精灵的关注。$B$B我的目标就是查出为什麽会发生这样的事并将其制止。';
