UPDATE `locales_broadcast_text` SET `male_text_loc4` = '你好，朋友。我是军官普尔哈特，隶属于银色黎明这个世界性的组织。我们的目标非常简单─与艾泽拉斯的一切邪恶力量进行顽强而持久的战斗。我们不是一个政治团体，也不想成为那样的团体。为了银色黎明的伟大目标，我们将联盟和部落的成员都当作并肩作战的朋友来看待!$B$B为了黎明而战，我的$g兄弟:姐妹;!' WHERE `entry` = 6870 AND `male_text_loc4` = '你好，朋友。我是军官普尔哈特，隶属於银色黎明这个世界性的组织。我们的目标非常简单─与艾泽拉斯的一切邪恶力量进行顽强而持久的战斗。我们不是一个政治团体，也不想成为那样的团体。为了银色黎明的伟大目标，我们将联盟和部落的成员都当作并肩作战的朋友来看待!$B$B为了黎明而战，我的$g兄弟:姐妹;!';
UPDATE `locales_broadcast_text` SET `male_text_loc4` = '银色黎明向你致敬，$c!我叫莱斯巴克，是银色黎明委派的装备和物资军需官。$B$B当你接受任命，同邪恶力量作战时 - 以此搏取得我们的尊重和信任 - 你会从军官普尔哈特那儿获得勇气勋章。勋章有两个用途:可增加自己的声望，或是用于获取特殊物品。$B$B随着你在银色黎明中地位的提高，你会发现有更多的物品能让你挑选。' WHERE `entry` = 6879 AND `male_text_loc4` = '银色黎明向你致敬，$c!我叫莱斯巴克，是银色黎明委派的装备和物资军需官。$B$B当你接受任命，同邪恶力量作战时 - 以此搏取得我们的尊重和信任 - 你会从军官普尔哈特那儿获得勇气勳章。勳章有两个用途:可增加自己的声望，或是用於获取特殊物品。$B$B随着你在银色黎明中地位的提高，你会发现有更多的物品能让你挑选。';
