UPDATE `locales_quest` SET `OfferRewardText_loc4` = '棒极了─毫无疑问，这些晨光麦会在适当时候派上用场。我们知道暗夜精灵也在进行关于这些草药的研究，但是我们还不清楚如果他们有所发现的话，这些草药将用于何种目的。大德鲁伊认为我们应该继续收购晨光麦，直到我们找出其中的奥秘。$B$B这是给你的，$N。我们感谢你提供的帮助。$B$B' WHERE `entry` = 3804 AND `OfferRewardText_loc4` = '棒极了─毫无疑问，这些晨光麦会在适当时候派上用场。我们知道暗夜精灵也在进行关於这些草药的研究，但是我们还不清楚如果他们有所发现的话，这些草药将用於何种目的。大德鲁伊认为我们应该继续收购晨光麦，直到我们找出其中的奥秘。$B$B这是给你的，$N。我们感谢你提供的帮助。$B$B';
