UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我们暗夜精灵很了解这份报告中所描绘的恐怖的场景。珊蒂斯派你把这份报告送到我这里来，这是个明智的决定。$B$B这些生物很快就吞噬菲拉斯，我们一定要消灭它们。你和其他信差看到的那些昆虫被称作异种蝎，它们是联盟和部落将要面对的共同威胁。$B$B我发誓要在异种蝎毁灭我们之前解决它们。$B$B' WHERE `entry` = 4267 AND `OfferRewardText_loc4` = '我们暗夜精灵很了解这份报告中所描绘的恐怖的场景。珊蒂斯派你把这份报告送到我这里来，这是个明智的决定。$B$B这些生物很快就吞噬菲拉斯，我们一定要消灭它们。你和其他信差看到的那些昆虫被称作异种蠍，它们是联盟和部落将要面对的共同威胁。$B$B我发誓要在异种蠍毁灭我们之前解决它们。$B$B';
