UPDATE `locales_quest` SET `OfferRewardText_loc4` = '从人类的角度来说，格雷戈是个足智多谋的人。他跟热砂企业打交道已经有些日子了，在地精的谈判「艺术」方面俨然成了个专家。虽然地精只对付钱最多的人表示忠诚，但是他们也明白并且尊重外交的价值。这样他们才能不断有新的顾客……$B$B不管怎么样，银色黎明需要你的帮助。请收下这个，谢谢你。$B$B' WHERE `entry` = 6029 AND `OfferRewardText_loc4` = '从人类的角度来说，格雷戈是个足智多谋的人。他跟热砂企业打交道已经有些日子了，在地精的谈判「艺术」方面俨然成了个专家。虽然地精只对付钱最多的人表示忠诚，但是他们也明白并且尊重外交的价值。这样他们才能不断有新的顾客……$B$B不管怎麽样，银色黎明需要你的帮助。请收下这个，谢谢你。$B$B';
