UPDATE `locales_quest` SET `OfferRewardText_loc4` = '笼罩着冬幕的传奇与故事在这几年中已经慢慢地由广为人知变得较为隐密了。我知道地精们为了他们自己而正在帮忙提倡这个节庆，而我们族人的反应至少在某种形式上对于保住这些传说是有帮助的。$B$B你想要越过物质并且学习我们的过去是值得敬佩的特质，年轻的$C。我向你的智慧致敬。$B$B' WHERE `entry` = 7061 AND `OfferRewardText_loc4` = '笼罩着冬幕的传奇与故事在这几年中已经慢慢地由广为人知变得较为隐密了。我知道地精们为了他们自己而正在帮忙提倡这个节庆，而我们族人的反应至少在某种形式上对於保住这些传说是有帮助的。$B$B你想要越过物质并且学习我们的过去是值得敬佩的特质，年轻的$C。我向你的智慧致敬。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '实在是太棒了，$N!你又帮了我的忙，谢谢你。$B$B非常感谢!$B$B也许我给的报酬比不上你从别人那里得到的，但是你在热砂企业地精社群中的声望将大大提升。如果你还有什么事，尽管找我说就好了!$B$B' WHERE `entry` = 7725 AND `OfferRewardText_loc4` = '实在是太棒了，$N!你又帮了我的忙，谢谢你。$B$B非常感谢!$B$B也许我给的报酬比不上你从别人那里得到的，但是你在热砂企业地精社群中的声望将大大提升。如果你还有什麽事，尽管找我说就好了!$B$B';
