UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，谢谢你，$N!亚布会用得到它们的。我不知道他准备用这些东西来干什么，但亚布是个聪明的小地精……他聪明得几乎有些狡猾了……$B$B如果他喜欢吃人，那他简直就是个彻头彻尾的巨魔了!$B$B拿着这个，$N。这些奖券是你的了。$B$B' WHERE `entry` = 7898 AND `OfferRewardText_loc4` = '啊，谢谢你，$N!亚布会用得到它们的。我不知道他准备用这些东西来干什麽，但亚布是个聪明的小地精……他聪明得几乎有些狡猾了……$B$B如果他喜欢吃人，那他简直就是个彻头彻尾的巨魔了!$B$B拿着这个，$N。这些奖券是你的了。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '继续追杀祖尔格拉布巨魔。要让哈卡明白，这个世界不会屈从于他的强大意志。$B$B' WHERE `entry` = 8103 AND `OfferRewardText_loc4` = '继续追杀祖尔格拉布巨魔。要让哈卡明白，这个世界不会屈从於他的强大意志。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这么说，你已经跟那个老矮人詹斯·铁靴谈过话，知道丢失的摩沙鲁石板的秘密了?那个爱管闲事的勘察员……$B$B没关系。要挽救世界，现在已经太晚了。哈卡已经重获新生，他的力量还在继续增长中……他就在古老的巨魔王国祖尔格拉布!他来了!他将再次使世界笼罩在血腥和恐怖之中!$B$B谢谢你，$N。在你的帮助下，夺魂者又回来了!$B$B' WHERE `entry` = 8181 AND `OfferRewardText_loc4` = '这麽说，你已经跟那个老矮人詹斯·铁靴谈过话，知道丢失的摩沙鲁石板的秘密了?那个爱管闲事的勘察员……$B$B没关系。要挽救世界，现在已经太晚了。哈卡已经重获新生，他的力量还在继续增长中……他就在古老的巨魔王国祖尔格拉布!他来了!他将再次使世界笼罩在血腥和恐怖之中!$B$B谢谢你，$N。在你的帮助下，夺魂者又回来了!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你拿到头颅了!你阻止了哈卡继续劫掠我们的神之力量，并削弱了哈卡!$B$B你做出了英雄般的壮举，$N。愿这些巨魔头颅的主人在他们的鲜血流尽之后得到宽恕。$B$B' WHERE `entry` = 8201 AND `OfferRewardText_loc4` = '你拿到头颅了!你阻止了哈卡继续劫掠我们的神之力量，并削弱了哈卡!$B$B你做出了英雄般的壮举，$N。愿这些巨魔头颅的主人在他们的鲜血流尽之後得到宽恕。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '的确，这是最幸运的事了。如果这些生物能维持永远的和平，对我们在卡林多的事务很有助益…这项事务是暗夜精灵们无法自行解决的。我会立即通知其他联盟的领导者，并会发送进一步的公文!$B$B至于你，$N…你在外交手腕和行为上都表现了你的勇气。谢谢你，整个联盟也感谢你。$B$B' WHERE `entry` = 8484 AND `OfferRewardText_loc4` = '的确，这是最幸运的事了。如果这些生物能维持永远的和平，对我们在卡林多的事务很有助益…这项事务是暗夜精灵们无法自行解决的。我会立即通知其他联盟的领导者，并会发送进一步的公文!$B$B至於你，$N…你在外交手腕和行为上都表现了你的勇气。谢谢你，整个联盟也感谢你。$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '继续保持，$N。我们地精没那么健忘!$B$B' WHERE `entry` = 9268 AND `OfferRewardText_loc4` = '继续保持，$N。我们地精没那麽健忘!$B$B';
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这是什么?要是我没猜错，这个火焰应该是从奥格玛中心拿到的吧!它燃烧的热度反映出兽人和巨魔凶猛的内心。真是为我们的收集品画龙点睛 - 从敌人的巢穴中偷取神圣的火焰，你真勇敢!$B$B不晓得其他城市里潜伏着什么样的力量……$B$B' WHERE `entry` = 9324 AND `OfferRewardText_loc4` = '这是什麽?要是我没猜错，这个火焰应该是从奥格玛中心拿到的吧!它燃烧的热度反映出兽人和巨魔凶猛的内心。真是为我们的收集品画龙点睛 - 从敌人的巢穴中偷取神圣的火焰，你真勇敢!$B$B不晓得其他城市里潜伏着什麽样的力量……$B$B';

