UPDATE `locales_quest` SET `RequestItemsText_loc4` = '这台「冬青保存机」第一眼看起来还满坚固的，但是经过仔细的检查之后，你发现它上面有些地精式的改造。不过，你的烹饪技能使得你可以理解它这台机器是如何运作的。$B$B机器里面已经有了新鲜的冬青了－－你只需要提供一些石中盐跟5个金币就可以让这台机器运作起来。' WHERE `entry` = 8763 AND `RequestItemsText_loc4` = '这台「冬青保存机」第一眼看起来还满坚固的，但是经过仔细的检查之後，你发现它上面有些地精式的改造。不过，你的烹饪技能使得你可以理解它这台机器是如何运作的。$B$B机器里面已经有了新鲜的冬青了－－你只需要提供一些石中盐跟5个金币就可以让这台机器运作起来。';
