UPDATE `locales_page_text` SET `Text_loc4` = REPLACE(`Text_loc4`, '盗贼的许多能力', '潜行者的许多能力') WHERE `entry` = 50682 AND `Text_loc4` LIKE '%盗贼的许多能力%';
